export const KB = [{"title":"النشأة والتاريخ","path":["عن الجامعة"],"facts":["الإنشاء: أُنشئت جامعة جازان بموجب الأمر الملكي رقم 6616/م ب وتاريخ 12/5/1426هـ الموافق 19/6/2005م.","الكليات النواة: كليات الطب، والهندسة، وعلوم الحاسب ونظم المعلومات، وكلية المجتمع.","الكليات التي ضُمّت للجامعة لاحقاً: كلية المعلمين، وتأسست عام 1401هـ (1981م)، كليات التربية للبنات، وتأسست عام 1412هـ (1992م).","حجم الجامعة بنهاية عام 1435هـ (2014م): 23 كلية، و4 وكالات، و9 عمادات، و8 معاهد ومراكز ووحدات مساندة.","الطلاب: أكثر من 56,000 طالب وطالبة بنهاية عام 1436هـ.","أعضاء هيئة التدريس ومن في حكمهم: نحو 2,500 في بداية عام 1436هـ.","المدينة الجامعية: خُصّصت لها أرض مساحتها 9,000,000 م² على ساحل البحر الأحمر شمال مدينة جازان، بعض مشروعاتها اكتمل، وبعضها قارب الاكتمال، وكثير منها قيد التنفيذ.","آخر تحديث للصفحة: الخميس 11 ربيع الأول 1447هـ."],"src":"https://www.jazanu.edu.sa/en/university-history"},{"title":"الرؤية والرسالة والقيم","path":["عن الجامعة"],"facts":["الرؤية: \"A regionally distinct university with its educational output, innovative research, and community services.\"","الرسالة: \"We teach, research and innovate to contribute to building a vibrant society.\"","القيم: المواطنة : \"Pride in the national identity and a sense of social responsibility.\"، الانتماء : \"a feeling of commitment and initiative towards the goals and objectives of the university.\"، المسؤولية : \"Adherence to ethical standards and work values.\"، التميز : \"The application of standard practices and offering quality services.\"، بناء القدرات : \"Investing in human capital.\"، العمل الجماعي : \"Promoting cooperation and imbibing the team spirit.\"."],"src":"https://www.jazanu.edu.sa/en/university-history/vision-and-mission"},{"title":"كلمة رئيس الجامعة والسيرة الذاتية","path":["عن الجامعة"],"facts":["المنصب: معالي رئيس جامعة جازان منذ 17 مايو 2024م. كان قبلها قائماً بأعمال رئيس الجامعة من 28 مارس إلى 16 مايو 2024م.","ملخص الكلمة: يرحّب الرئيس بزوّار الموقع، يذكر أن الجامعة، بدعم من الدولة، تسعى إلى بناء أفراد يمتلكون المعرفة والمهارات والخبرات اللازمة لمواكبة المتغيرات والإسهام في تحقيق رؤية المملكة 2030، تقوم استراتيجية الجامعة على معايير الجودة والتحسين المستمر والشفافية، وعلى توثيق الصلة بمنسوبيها الأكاديميين والإداريين والفنيين وبالمجتمع، رسالتها التعليم والبحث والابتكار والإسهام في بناء مجتمع حيوي، وتسترشد بقيم المواطنة والانتماء والمسؤولية والعمل الجماعي.","المؤهلات العلمية: دكتوراه في الإرشاد النفسي ، 1999م، جامعة هل ، المملكة المتحدة، ماجستير في الإرشاد النفسي، 1994م، جامعة هل، المملكة المتحدة، بكالوريوس علم النفس، 1988م، جامعة الملك سعود – فرع أبها.","الخبرات المهنية: رئيس جامعة جازان: 2024م – حتى الآن، قائم بأعمال رئيس الجامعة: 2024م، وكيل الجامعة للدراسات العليا والبحث العلمي: 2017–2024م، قائم بأعمال وكيل الجامعة للتطوير وريادة الأعمال: 2022–2023م، قائم بأعمال وكيل الجامعة للدراسات العليا والبحث العلمي: 2016–2017م، عميد كلية التربية بجامعة جازان: 2009–2016م، وكيل كلية التربية بجامعة الملك خالد: 2007–2009م، رئيس قسم علم النفس التربوي بجامعة الملك خالد: 2000–2007م، مهام إشرافية أخرى بجامعة الملك خالد: 2001–2009م.","العضويات الحالية: مجلس شؤون الجامعات، المجلس التنفيذي لاتحاد الجامعات العربية، اللجان العليا والتنفيذية لبرامج التوطين بمنطقة جازان، مجلس إدارة مركز الأمير محمد بن ناصر للتوعية الوقائية.","اللجان الدائمة (12 لجنة): منها: مجلس الجامعة، المجلس العلمي، ويرأسه، لجنة ضمان الجودة والاعتماد الأكاديمي، الإشراف على الخطة الاستراتيجية.","الجمعيات: عضو مؤسس في مجلس إدارة جمعية الأزمات النفسية والاجتماعية بمنطقة جازان، رئيس مؤسس للجمعية السعودية للإرشاد الطلابي.","الإنتاج العلمي: 26 بحثاً، و31 ورقة في مؤتمرات، و3 كتب، و23 مشروعاً ممولاً، والإشراف على 50 رسالة علمية.","الدورات التدريبية: في ضمان جودة البحث، والتخطيط الاستراتيجي، وإدارة التغيير، والتعلم الإلكتروني، والعلاج المعرفي السلوكي، وغيرها.","الجوائز والمنح: منحة أرامكو (1412هـ)، جائزة الأمير خالد الفيصل للتفوق العلمي (1408هـ)، شهادة تقدير من مدير جامعة الملك سعود (1408هـ)، خطابات شكر وشهادات من جهات وطنية ودولية."],"src":"https://www.jazanu.edu.sa/en/president"},{"title":"القيادات العليا: الرئيس والوكلاء (حسب أخبار الجامعة)","path":["عن الجامعة"],"facts":["رئيس الجامعة السابق: أ.د. مرعي بن حسين القحطاني : ورد بهذه الصفة في أخبار بتاريخ 27 محرم 1442هـ، و4 صفر 1442هـ، و20 جمادى الأولى 1444هـ.","وكلاء الجامعة حسب خبر بتاريخ 1 صفر 1442هـ. هذه الأسماء تاريخية وقد لا تمثل التشكيل الحالي","أ.د. محمد بن علي معشي — المنصب: وكيل الجامعة","أ.د. محمد بن حسن أبوراسين — المنصب: وكيل الجامعة للدراسات العليا والبحث العلمي","د. حسن بن عبدالله إسحاق — المنصب: وكيل الجامعة للشؤون الأكاديمية","د. نايف بن جحشور عزيبي — المنصب: وكيل الجامعة للتطوير وريادة الأعمال","أ.د. عائشة بنت حسن زكري — المنصب: وكيلة الجامعة لشؤون الطالبات","في خبر بتاريخ 23 ربيع الأول 1444هـ: ورد أ.د. محمد أبوراسين بصفته وكيل الجامعة للدراسات العليا والبحث العلمي."],"src":"https://www.jazanu.edu.sa/en/media-center/news/vice-presidents-jazan-university-homeland-thriving-era-achievements-and-mega"},{"title":"هيئات الجامعة (الوكالات والكليات والعمادات والمراكز)","path":["عن الجامعة"],"facts":["الوكالات (5): وكالة الجامعة، وكالة الجامعة للتطوير وريادة الأعمال، وكالة الجامعة للدراسات العليا والبحث العلمي، وكالة الجامعة للشؤون الأكاديمية، وكالة الجامعة لشؤون الطالبات.","الكليات: 23 كلية: 21 منها تمنح درجة البكالوريوس للطلاب والطالبات، وواحدة تمنح درجة الدبلوم، كما ورد في الصفحة، تذكر الصفحة أيضاً كليات أُعيدت هيكلتها: كلية المعلمين، وكلية التربية للبنات، وكلية إعداد المعلمين، وكلية التربية بفرسان، وكلية المجتمع للبنات.","كلية المجتمع — سنة الإنشاء (هـ / م): 1418 / 1997، عدد الأقسام: 2","كلية الطب — سنة الإنشاء (هـ / م): 1421 / 2000، عدد الأقسام: 19","كلية الهندسة — سنة الإنشاء (هـ / م): 1425 / 2004، عدد الأقسام: 7","كلية علوم الحاسب وتقنية المعلومات — سنة الإنشاء (هـ / م): 1425 / 2004، عدد الأقسام: 3","كلية العلوم الطبية التطبيقية — سنة الإنشاء (هـ / م): 1426 / 2005، عدد الأقسام: 5","كلية العلوم — سنة الإنشاء (هـ / م): 1426 / 2005، عدد الأقسام: 4","كلية الصيدلة — سنة الإنشاء (هـ / م): 1429 / 2008، عدد الأقسام: 5","كلية إدارة الأعمال — سنة الإنشاء (هـ / م): 1429 / 2008، عدد الأقسام: 7","كلية طب الأسنان — سنة الإنشاء (هـ / م): 1429 / 2008، عدد الأقسام: 4","كلية التصاميم والعمارة — سنة الإنشاء (هـ / م): 1430 / 2009، عدد الأقسام: 6","كلية الآداب والعلوم الإنسانية — سنة الإنشاء (هـ / م): 1430 / 2009، عدد الأقسام: 7","كلية التربية — سنة الإنشاء (هـ / م): 1430 / 2009، عدد الأقسام: 9","الكلية الجامعية بصامطة — سنة الإنشاء (هـ / م): 1430 / 2009، عدد الأقسام: 7","الكلية الجامعية بفرسان — سنة الإنشاء (هـ / م): 1430 / 2009، عدد الأقسام: 5","الكلية الجامعية بالدرب — سنة الإنشاء (هـ / م): 1430 / 2009، عدد الأقسام: 8","الكلية الجامعية بالعارضة — سنة الإنشاء (هـ / م): 1431 / 2010، عدد الأقسام: 5","كلية الصحة العامة وطب المناطق الحارة — سنة الإنشاء (هـ / م): 1432 / 2011، عدد الأقسام: 8","كلية التمريض — سنة الإنشاء (هـ / م): 1432 / 2011، عدد الأقسام: 9","كلية الشريعة والقانون — سنة الإنشاء (هـ / م): 1432 / 2011، عدد الأقسام: 3","الكلية الجامعية بالداير — سنة الإنشاء (هـ / م): 1433 / 2012، عدد الأقسام: 5","الكلية الجامعية بصبيا — سنة الإنشاء (هـ / م): 1433 / 2012، عدد الأقسام: 9","الكلية الجامعية بأبي عريش — سنة الإنشاء (هـ / م): 1434 / 2013، عدد الأقسام: 6","كلية المجتمع بمحافظة بيش — سنة الإنشاء (هـ / م): 1434 / 2013، عدد الأقسام: 7","العمادات المساندة (9): عمادة البحث العلمي، عمادة الدراسات العليا، عمادة التطوير الأكاديمي، عمادة القبول والتسجيل، عمادة التعلم الإلكتروني والتعليم عن بعد، عمادة شؤون الطلاب، عمادة شؤون المكتبات، عمادة خدمة المجتمع والتعليم المستمر، عمادة الموارد البشرية.","المعاهد والمراكز والوحدات: تذكر الصفحة أن عددها 8، لكنها تسرد 13: معهد البحوث والخدمات الاستشارية، مركز أبحاث ودراسات البيئة، مركز الأبحاث الطبية، مركز أبحاث المخدرات والسموم، معهد اللغة الإنجليزية، وحدة التوعية الفكرية، وحدة قادة المستقبل، مركز الابتكار وريادة الأعمال، وحدة تطوير المشاريع، Jazan University Central، كما ورد، مركز الوثائق والمحفوظات، مركز التميز في التعليم والتعلم، وحدة علاقات الخريجين والتوظيف.","ملاحظات: قد تكون بيانات هذه الصفحة قديمة، فهي تتوافق مع وضع عام 1435هـ تقريباً."],"src":"https://www.jazanu.edu.sa/en/university-history/strategic-plan"},{"title":"وكالة الجامعة","path":["عن الجامعة"],"facts":["الإنشاء: بقرار مجلس التعليم العالي رقم 8/39/1426 وتاريخ 25/10/1426هـ.","الرؤية: \"Achieving quality standards and keep abreast of global developments\"، بهدف استدامة التميز في المهام والمسؤوليات المسندة إليها.","الجهات المرتبطة بالوكالة (8): عمادة الموارد البشرية، الإدارة العامة للشؤون الإدارية والمالية، الإدارة العامة للمشاريع، الإدارة العامة للتشغيل والصيانة والنظافة، إدارة أملاك الجامعة وأجور الدور، إدارة الحركة والنقل، مكتب الاتصال الخارجي، إدارة الموارد والتنمية المستدامة.","آخر تحديث للصفحة: الأحد 19 ربيع الآخر 1447هـ."],"src":"https://www.jazanu.edu.sa/en/administration/vice-rectorates/vice-president"},{"title":"وكالة الجامعة للشؤون الأكاديمية","path":["عن الجامعة"],"facts":["الإنشاء: بموجب الأمر السامي رقم 5150/م ب وتاريخ 3/7/1429هـ: استند الأمر إلى قرار مجلس التعليم العالي رقم 17/49/1429 المتخذ في جلسته التاسعة والأربعين بتاريخ 4/4/1429هـ.","الرؤية: \"Creating a distinguished and pioneering academic environment.\"","الرسالة (ملخصة): تقديم برامج أكاديمية متميزة وفق معايير الجودة العالمية واحتياجات سوق العمل، من خلال رفع مستوى أداء كليات الجامعة ودعم الطلاب وأعضاء هيئة التدريس."],"src":"https://jazanu.edu.sa/en/administration/vice-rectorates/vice-president-academic-affairs"},{"title":"وكالة الجامعة للدراسات العليا والبحث العلمي","path":["عن الجامعة"],"facts":["الإنشاء: تستند الصفحة إلى الأمر الملكي رقم 6616/م ب، ويرد تاريخه فيها بصيغة 05/12/1426.","الرؤية: التميز في البحث العلمي وتطوير برامج دراسات عليا عالية المستوى تسهم في بناء مجتمع المعرفة. النص الإنجليزي يبدأ بـ \"Excellence in scientific research, and the development of high-level postgraduate programs\".","دورها: تطوير الجامعة عبر: البحث العلمي والشراكات البحثية، المراكز البحثية المتخصصة وكراسي البحث العلمي، المجلس العلمي ومجلة علمية متخصصة، الاتفاقيات مع الجهات المحلية والدولية.","مهامها: تشجيع البحوث المشتركة بين أعضاء هيئة التدريس والبرامج والمعاهد البحثية، وضع آلية تشجّع أعضاء هيئة التدريس على حضور المؤتمرات والندوات المحلية والدولية، تقديم مكافآت وحوافز للجهود البحثية التي تخدم المجتمع."],"src":"https://jazanu.edu.sa/en/administration/vice-rectorates/vice-president-graduate-studies-research"},{"title":"الجامعة في أرقام","path":["عن الجامعة"],"facts":["الأرقام المعروضة حالياً في الصفحة الرئيسية للموقع","أعضاء هيئة التدريس — العدد: 2,489","الموظفون الإداريون — العدد: 1,706","الطلاب — العدد: +36 ألف","الكليات — العدد: 14","أرقام مختلفة في صفحات أخرى","الكليات: 23 كلية بنهاية 1435هـ في صفحة النشأة وصفحة هيئات الجامعة، مقابل 14 في الصفحة الرئيسية: المصادر: و.","الطلاب: أكثر من 56,000 بنهاية 1436هـ (المصدر، أكثر من 45,000 طالب وطالبة تابعوا دراستهم عن بُعد، ويذكر الخبر نفسه أن النظام استوعب أكثر من 50,000، وذلك في خبر بتاريخ 4 صفر 1442هـ (المصدر.","أعضاء هيئة التدريس: نحو 2,500 في بداية 1436هـ (المصدر","الوكالات: 4 بنهاية 1435هـ في صفحة النشأة، مقابل 5 في صفحة هيئات الجامعة."],"src":"https://www.jazanu.edu.sa/en"},{"title":"المدينة الجامعية والمرافق","path":["عن الجامعة"],"facts":["المدينة الجامعية: مساحتها 9,000,000 م² على ساحل البحر الأحمر شمال مدينة جازان، ووُضع حجر أساسها عام 1427هـ (2006م)، كما سبق في قسم النشأة.","المجمع الأكاديمي بمحلية (للطالبات): من خبر زيارة وزير التعليم لقيادات الجامعة بتاريخ 20 جمادى الأولى 1444هـ: المرافق: 184 قاعة دراسية، و83 مختبراً، و20 قاعة تدريب وورش عمل، ومسرح يتسع لـ450 شخصاً، الكليات: الهندسة، والعلوم، وعلوم الحاسب وتقنية المعلومات، والتصاميم والعمارة، إضافة إلى برنامج صحي متكامل، الوحدات الأخرى: 5 عمادات مساندة، و12 قسماً، ومعهد اللغة الإنجليزية.","المستشفى الجامعي (في المدينة الجامعية): حسب الخبر نفسه: تعمل فيه العيادات الخارجية والاستشارية، التخصصات: الباطنة، والجراحة، والنساء والولادة، والأطفال، والطوارئ، والعلاج الطبيعي، والطب التأهيلي، والمختبر، والصيدلية، والأشعة، كان مقرراً حينها تشغيل جراحات اليوم الواحد خلال شهرين."],"src":"https://www.jazanu.edu.sa/en/university-history"},{"title":"الاعتماد المؤسسي","path":["عن الجامعة"],"facts":["حالة الجامعة: صفحة «نبذة عن الجامعة» في منصة معهد البحوث والخدمات الاستشارية تصف الجامعة بأنها جامعة حكومية معتمدة تحت مظلة وزارة التعليم، \"حاصلة على الاعتماد الأكاديمي من هيئة تقويم التعليم والتدريب (إتقان)\"، خبر بتاريخ 4 صفر 1442هـ يذكر حصول الجامعة على الاعتماد المؤسسي الكامل من المركز الوطني للتقويم والاعتماد الأكاديمي.","صفحة الاعتماد المؤسسي بعمادة التطوير الأكاديمي: تشرح الإجراءات دون ذكر تاريخ أو حالة اعتماد الجامعة: الجهة: المركز الوطني للتقويم والاعتماد الأكاديمي، أنواع الاعتماد، كامل، مشروط: يتحول إلى كامل بعد استيفاء الشروط الواردة في تقرير المراجعة وإرسال الأدلة والشواهد، مراحل الاعتماد (6)، التقدم بالطلب، التحقق من التأهل: ترسل المؤسسة وثائق متطلبات التأهل، ويراجعها المستشارون ثم يصدر تقرير الفحص، تشكيل فريق المراجعين وتحديد موعد الزيارة، ثم عقد لقاء تهيئة، الزيارة الميدانية لمدة 4 أيام، تتضمن مقابلات وزيارة مرافق وفحص وثائق، ثم تُعدّ المسودة الأولية لتقرير المراجعة، قرار الاعتماد: تراجع اللجنة الاستشارية التقرير، ثم يعتمد مجلس الاعتماد التوصيات، المتابعة الدورية: تقارير سنوية، وزيارة متابعة عند الحاجة."],"src":"https://platform.jazanu.edu.sa/university-brief"},{"title":"التصنيفات","path":["عن الجامعة"],"facts":["تصنيف QS للمنطقة العربية، نسخة 2023: حسب خبر بتاريخ 23 ربيع الأول 1444هـ: جاءت الجامعة في الفئة 91–100، متقدمة 30 مركزاً عن عام 2022م، شملت المؤشرات المذكورة: الجوانب البحثية والتعليمية، والتنوع والحضور الدولي، والكفاءات التعليمية، والسمعة البحثية، وتوظيف الخريجين، ورد في الخبر: د. علي هندي (عميد التطوير الأكاديمي)، ود. هيثم حديدي (وكيل عمادة التطوير الأكاديمي)، وأ.د. محمد أبوراسين (وكيل الجامعة للدراسات العليا والبحث العلمي).","تصنيف التايمز للجامعات، نسخة 2023: حسب الخبر نفسه: عالمياً: في الفئة 401–500، محلياً: السابعة بين الجامعات السعودية الحكومية والأهلية.","بحوث كورونا: ضمن أفضل 10 جامعات ومؤسسات بحثية في المملكة في أبحاث فيروس كورونا، وفق مدينة الملك عبدالعزيز للعلوم والتقنية، حسب خبر 4 صفر 1442هـ."],"src":"https://jazanu.edu.sa/en/media-center/news/news44032405"},{"title":"إنجازات (من خبر «دعم القيادة الكريم والإنجازات المتتالية» – 4 صفر 1442هـ)","path":["عن الجامعة"],"facts":["السياق: مرور 15 عاماً على تأسيس الجامعة.","الاعتماد: حصلت على الاعتماد المؤسسي الكامل من المركز الوطني للتقويم والاعتماد الأكاديمي.","التعليم الإلكتروني: أكثر من 45,000 طالب وطالبة واصلوا الدراسة عن بُعد، والنظام استوعب أكثر من 50,000، 16 دليلاً تدريبياً، تأهيل ودعم أكثر من 23 وحدة تعلم إلكتروني، نحو 60 عضو هيئة تدريس يتحدثون العربية والإنجليزية، 67 دورة تدريبية على استخدام النظام.","عيادات طب الأسنان: 287 عيادة، نحو 10,563 ملف مريض في العام السابق: 5,823 رجلاً و4,735 امرأة، كما ورد.","الدراسات العليا: أكثر من 120 طالباً في 27 برنامجاً للدراسات العليا عام 1441هـ.","الطلاب الدوليون: 808 طلاب منح من 33 دولة.","برامج الدبلوم المجتمعية: زيادة القبول 30% في 1442هـ، أكثر من 6,542 متقدماً، 17 برنامجاً متاحاً.","التدريب الصيفي (1441هـ): 16 برنامجاً عن بُعد في 5 فئات، مدة كل منها 6 ساعات.","تطوير أعضاء هيئة التدريس (1441هـ): تدريب 1,245 عضواً، منهم 1,186 محلياً و59 دولياً.","تطوير الموظفين (1440/1441هـ): تدريب 1,105 موظفين.","جائحة كورونا: تحويل مبنى سكن الطلاب رقم 2 إلى مقر عزل (5 طوابق، 220 غرفة، 660 سريراً)، التخطيط لمركز طبي بسعة 220 سريراً بالتنسيق مع صحة جازان.","رئيس الجامعة حينها: د. مرعي بن حسين القحطاني."],"src":"https://www.jazanu.edu.sa/en/media-center/news/jazan-universitygenerous-leadership-support-and-successive-achievements"},{"title":"الكليات","path":[],"facts":["تذكر الصفحة الرئيسية لموقع الجامعة أن عدد الكليات 14 كلية، وأن عدد أعضاء هيئة التدريس 2,489، والإداريين 1,706، والطلاب أكثر من 36 ألفاً.","والكليات التي تعرضها الصفحة الرئيسية حالياً مع أقسامها هي: 13 كلية رئيسية، ثم مجموعة بعنوان «الكليات الجامعية والكليات التطبيقية» فيها 7 كليات في المحافظات، وتظهر الكلية التطبيقية في صفحة مستقلة على الموقع.","الموقع لا يذكر صراحةً أيّ الكليات تدخل في رقم الـ14.","كلية الطب — عدد الأقسام: 11","كلية طب الأسنان — عدد الأقسام: 4، العميد: (صفحة بعنوان «عميدة الكلية»، ولم يُستخرج الاسم)","كلية التمريض والعلوم الصحية — عدد الأقسام: 8","كلية الصيدلة — عدد الأقسام: 5 (كما وردت، وفي التسميات تداخل)","كلية الصحة العامة وطب المناطق الحارة — عدد الأقسام: 3، العميد: د. منال بنت علي المالكي","كلية الهندسة وعلوم الحاسب — عدد الأقسام: غير محسوم (انظر التفاصيل)، العميد: Dr. Mohammed Y Aalsalem","كلية التصميم والعمارة — عدد الأقسام: 3، العميد: (صفحة بعنوان «عميدة الكلية»، ولم يُستخرج الاسم)","كلية الأعمال — عدد الأقسام: 3 حسب صفحة الكلية، و4 حسب الصفحة الرئيسية","كلية العلوم — عدد الأقسام: 5","كلية التقنية الصناعية التطبيقية ببيش — عدد الأقسام: 3","كلية التربية — عدد الأقسام: 7 حسب الصفحة الرئيسية، و8 حسب صفحة الكلية","كلية الآداب والعلوم الإنسانية — عدد الأقسام: 7","كلية الشريعة والقانون — عدد الأقسام: 3، العميد: (لم يُذكر الاسم، والبريد mjaddoh@jazanu.edu.sa)","الكلية التطبيقية — العميد: Dr. Ali bin Abdulhadi Al-Almai","الكلية الجامعية بفرسان — عدد الأقسام: 4، العميد: Dr. Afaf Muhammad Ba Ba'ir","الكلية الجامعية بالدرب — عدد الأقسام: 5 حسب صفحة الكلية، و7 حسب الصفحة الرئيسية","الكلية الجامعية بالدائر — عدد الأقسام: 3 حسب صفحة الكلية، و5 حسب الصفحة الرئيسية","الكلية التطبيقية بالعارضة (وفي صفحتها: الكلية الجامعية بالعارضة) — عدد الأقسام: 3 في المصدرين، لكن الأقسام مختلفة","الكلية التطبيقية بصامطة — عدد الأقسام: 4","الكلية الجامعية بأبوعريش — عدد الأقسام: 4","الكلية الجامعية بصبيا — عدد الأقسام: 3"],"src":"https://www.jazanu.edu.sa/en/university-history/strategic-plan"},{"title":"كلية الطب","path":["الكليات"],"facts":["التأسيس: أُنشئت بالأمر السامي رقم 7/ب/15252 وتاريخ 18/11/1421هـ، لتأهيل الكوادر الطبية الوطنية وتلبية احتياجات المنطقة الصحية المتزايدة.","الرؤية: أن تكون مركزاً للتميز في التعليم الطبي وشريكاً فاعلاً في تعزيز الصحة بمنطقة جازان.","مهام الكلية: تكرر الصفحة التوجهات الاستراتيجية للجامعة، وهي بناء منظومة إدارية بمستوى عالمي، وتحقيق التميز المعرفي، وإحداث أثر اجتماعي واقتصادي.","الأقسام الأكاديمية (11): طب الأسرة والمجتمع، الطب الباطني، الجراحة، طب الأطفال، النساء والولادة، علم الأدوية السريري، علم وظائف الأعضاء، علم الأمراض، الكيمياء الحيوية الطبية، التشريح، الأحياء الدقيقة والطفيليات الطبية."],"src":"https://www.jazanu.edu.sa/en/colleges/collegeofmedicine"},{"title":"كلية طب الأسنان","path":["الكليات"],"facts":["الرؤية: أن تكون كلية رائدة في طب الأسنان من خلال تعليم وبحث متميزين ورعاية صحية مجتمعية.","الرسالة: تحقيق الجودة العالية في التعليم والبحث وخدمة المجتمع، عبر تعليم متميز في طب الأسنان، وممارسة مبنية على الدليل، وتقنيات متقدمة، لتخريج مهنيين أكفاء يقودون في مجتمعاتهم.","من أهدافها: الحصول على الاعتماد الأكاديمي للبرنامج من المركز الوطني للتقويم والاعتماد الأكاديمي ، وتطوير البنية التحتية، وتطبيق اللامركزية في اتخاذ القرار، واستقطاب طلاب أفضل إعداداً، وتقديم خدمات مجتمعية ونشر الوعي بصحة الفم.","نبذة: بدأت الدراسة فيها عام 2010 في مبنى أصغر، وتعمل الكلية الآن في مبنى حديث يضم التعليم والبحث والخدمات الصحية.","الأقسام الأكاديمية (4): جراحة الوجه والفكين وعلوم التشخيص، علوم طب الأسنان الوقائي، علوم استعاضة الأسنان، علوم طب الأسنان الترميمي.","البرامج: بكالوريوس طب الفم والأسنان وجراحتها. مدته 6 سنوات: سنة تحضيرية، و5 سنوات دراسية، ثم سنة امتياز تغطي تخصصات طب الأسنان كلها، برنامج التدريب (الامتياز)."],"src":"https://www.jazanu.edu.sa/en/colleges/college-dentistry"},{"title":"كلية التمريض والعلوم الصحية","path":["الكليات"],"facts":["حسب صفحة العلوم الطبية التطبيقية: أُنشئت الكلية في العام الجامعي 1427/1428هـ بالقرار رقم 22/37/1426، وبدأت ببرنامج تقنية المختبرات الطبية للطلاب: الرؤية: الريادة والتميز محلياً ودولياً، المهام: تخريج مهنيين صحيين متميزين يحسّنون الخدمات العلاجية والتشخيصية، وإعداد الخريجين للدراسات العليا، ونشر الوعي المجتمعي بطرق الوقاية من الأمراض المتوطنة في جنوب المملكة، وإشراك الطلاب في البحث العلمي.","حسب صفحة كلية التمريض: كانت في الأصل «الكلية الصحية للبنات»، ثم أُعيدت هيكلتها إلى «كلية التمريض والعلوم الصحية المساندة» بالأمر رقم 5088/ب وتاريخ 7/8/1432هـ، ثم تغير اسمها إلى «كلية التمريض» بموافقة وزارة التعليم رقم 71524 وتاريخ 27/8/1438هـ. وأقسامها بعد إعادة الهيكلة: التمريض، والرعاية التنفسية، والإسعاف والطوارئ: الرؤية: أن تكون منارة علمية رائدة محلياً ومتميزة إقليمياً في تعليم التمريض والبحث العلمي وخدمة المجتمع.","الأقسام الأكاديمية حسب الصفحة الرئيسية (8): تقنية المختبرات الطبية، العلاج الطبيعي، تقنية الأشعة التشخيصية، التغذية الإكلينيكية، العلاج التنفسي، الإسعاف والطوارئ، التمريض، الصحة العامة."],"src":"https://www.jazanu.edu.sa/en/colleges/college-applied-medical-sciences"},{"title":"كلية الصيدلة","path":["الكليات"],"facts":["الرؤية: التميز وطنياً في التعليم الصيدلي والبحث وخدمة المجتمع .","الرسالة: تحسين الصحة والاستخدام الآمن للدواء من خلال تعليم عالي الجودة، وبحث مبتكر، ومشاركة مجتمعية فاعلة، ومهارات ريادة الأعمال.","الأهداف: التميز الأكاديمي، والتميز البحثي، والتميز في الشراكة وخدمة المجتمع، والتميز التشغيلي.","الأقسام الأكاديمية كما وردت في الصفحة الرئيسية (5): الممارسة الإكلينيكية، علم الأدوية والسموم، الصيدلانيات، الكيمياء الصيدلية والعقاقير، العقاقير ، ويتداخل مسماه مع القسم السابق في الموقع."],"src":"https://www.jazanu.edu.sa/en/colleges/college-pharmacy"},{"title":"كلية الصحة العامة وطب المناطق الحارة","path":["الكليات"],"facts":["العميدة: د. منال بنت علي المالكي","نبذة: تكونت بإعادة هيكلة الكلية الصحية للبنين وكلية العلوم الصحية للبنات بجازان، وبدأت عام 2012. تذكر صفحتها أنها الكلية الوحيدة على المستوى الوطني والخليجي المتخصصة في طب المناطق الحارة، وأنها أُنشئت لمواجهة التحديات الصحية الخاصة بمناخ جازان المداري.","الرؤية: أن تُعرف محلياً ووطنياً بالتميز في التعليم والبحث وخدمة المجتمع.","الرسالة: تقديم تعليم وبحث وخدمات مبنية على الدليل في الصحة العامة وطب المناطق الحارة، لبناء مجتمع صحي ومسؤول.","الأقسام الأكاديمية (3): المعلوماتية الصحية، الوبائيات، التثقيف وتعزيز الصحة.","الدرجات: بكالوريوس في الأقسام الثلاثة: 4 سنوات (8 فصول)، تليها سنة امتياز تطبيقية، البرامج معتمدة من الهيئة السعودية للتخصصات الصحية، والاعتماد البرامجي من المركز الوطني للتقويم والاعتماد الأكاديمي قيد التنفيذ.","برامج ماجستير مخطط لها: طب المناطق الحارة، صحة الأم والطفل، المعلوماتية الصحية."],"src":"https://www.jazanu.edu.sa/en/colleges/college-public-health-and-tropical-medicine"},{"title":"كلية الهندسة وعلوم الحاسب","path":["الكليات"],"facts":["العميد: Dr. Mohammed Y Aalsalem","نبذة: تكونت بدمج كلية الهندسة وكلية علوم الحاسب وتقنية المعلومات، بهدف رفع جودة التعليم وتوسيع البرامج الأكاديمية.","الرؤية: الريادة محلياً وعالمياً في جودة التعليم والبحث العلمي والتعليم الهندسي والتقني.","الرسالة والأهداف: تقديم تعليم عالٍ في الهندسة وعلوم الحاسب لخريجي وخريجات الثانوية، تزويد الطلاب بالمعارف والمهارات الهندسية والتقنية لسوق العمل المحلي والعالمي، بناء شراكات مع القطاعات الصناعية والتقنية والحكومية والخاصة في البحث والتدريب والتوظيف، إعداد كوادر هندسية وتقنية منتجة ومبدعة ومبتكرة، تهيئة بيئة بحثية تخدم سوق العمل ورؤية المملكة 2030، تنمية الموارد المالية لدعم التعليم والبحث والابتكار.","الأقسام والوحدات كما وردت في الصفحة الرئيسية. فيها تسميات من الهيكل السابق وأخرى من الهيكل الجديد: أقسام بالمسمى الجديد، الهندسة المدنية والمعمارية، علوم الحاسب، الهندسة الكهربائية والشبكات، تخصصات أو أقسام هندسية مدرجة أيضاً، الهندسة الصناعية، الهندسة الكيميائية، الهندسة الكهربائية والإلكترونية، الهندسة المدنية، الهندسة الميكانيكية، الهندسة المعمارية، وحدة الهندسة العامة.","البرامج: بكالوريوس علوم الحاسب، هندسة الحاسب والشبكات ، ضمن قسم الهندسة الكهربائية والشبكات، بكالوريوس العلوم في الهندسة الميكانيكية، ماجستير الهندسة المدنية، ماجستير العلوم في الهندسة الميكانيكية."],"src":"https://www.jazanu.edu.sa/en/colleges/college-engineering-and-computer-science"},{"title":"كلية التصميم والعمارة","path":["الكليات"],"facts":["على الموقع صفحة بعنوان «عميدة الكلية»، لكن تعذّر استخراج اسمها.","الأقسام الأكاديمية (3): التصميم الداخلي، الفنون التطبيقية، العمارة."],"src":"https://www.jazanu.edu.sa/en"},{"title":"كلية الأعمال","path":["الكليات"],"facts":["التأسيس: عام 1429هـ (2008م)، بتوصية من مجلس الجامعة وموافقة مجلس التعليم العالي.","الرؤية: أن تكون كلية أعمال رائدة ومعترفاً بها إقليمياً.","الرسالة: تهيئة بيئة مبتكرة تعزز التميز في تعليم الأعمال والبحث وريادة الأعمال وخدمة المجتمع، مع التركيز على الجودة والتحسين المستمر.","الأهداف الاستراتيجية: الاستخدام الأمثل للمرافق التعليمية وتبني موارد تقنية المعلومات الحديثة، تطبيق ممارسات الحوكمة الرشيدة، إدارة الموارد البشرية وتطويرها بفاعلية، تحسين البرامج الأكاديمية، تطبيق أفضل الممارسات في العمليات الإدارية، رفع جودة البحث والابتكار وريادة الأعمال، تحسين الأداء الأكاديمي والمهارات المعرفية للطلاب، تحسين مخرجات الكلية والقيام بالمسؤولية الاجتماعية.","الأقسام: صفحة الكلية تذكر 3 أقسام متخصصة، ولا تسميها، الصفحة الرئيسية تذكر 4 أقسام، الإدارة والتسويق، المالية والمصرفية، المحاسبة والمالية، نظم المعلومات الإدارية.","البرامج: صفحة الكلية تذكر 6 برامج بكالوريوس، وماجستير إدارة الأعمال التنفيذي ، أي 7 برامج إجمالاً، برامج مسماة في صفحة «معلومات عن برامج البكالوريوس»، إدارة الأعمال، التسويق والتجارة الإلكترونية، إدارة السياحة والفنادق، المحاسبة، المالية والمصرفية، ماجستير إدارة الأعمال التنفيذي."],"src":"https://www.jazanu.edu.sa/en/colleges/cob"},{"title":"كلية العلوم","path":["الكليات"],"facts":["الرؤية: تحقيق الريادة الإقليمية في التعليم والبحث العلمي وخدمة المجتمع.","الرسالة: تقديم برامج أكاديمية متميزة وبحث مبتكر يلبي احتياجات التنمية وخدمة المجتمع.","الأهداف: بُنيت خطة الكلية بمنهجية الأداء المتوازن من أربعة منظورات: القدرة المؤسسية، والعمليات الداخلية، والموارد، وأصحاب المصلحة.","الأقسام الأكاديمية (5): الأحياء، الكيمياء، الفيزياء، الرياضيات، العلوم الفيزيائية.","للكلية وكالة لشطر الطالبات ."],"src":"https://www.jazanu.edu.sa/en/colleges/sci"},{"title":"كلية التقنية الصناعية التطبيقية ببيش","path":["الكليات"],"facts":["الرؤية: أن تكون مركزاً تعليمياً متميزاً في العلوم التقنية في المملكة.","الرسالة: إعداد فنيين مؤهلين لتلبية الاحتياجات الصناعية لمنطقة جازان والمملكة، عبر برامج تقنية عالية الجودة وشراكات استراتيجية.","الأهداف الاستراتيجية (الخطة الاستراتيجية 2021–2025): القيادة التشاركية، التميز الأكاديمي، الشراكة الاستراتيجية والاستشارات مع الصناعة، التركيز على الطالب، برامج تقنية مرنة، المسؤولية الاجتماعية.","الأقسام الأكاديمية (3): تقنية الهندسة الميكانيكية، تقنية الهندسة الكهربائية، تقنية الهندسة الكيميائية."],"src":"https://www.jazanu.edu.sa/en/colleges/college-applied-industrial-technology-cait"},{"title":"كلية التربية","path":["الكليات"],"facts":["المقر: شطر الطلاب في مجمع الكليات بأبوعريش، وشطر الطالبات في مجمع الكليات بصبيا.","الرؤية: أن تكون مؤسسة رائدة للمعرفة والتعلم، تنهض بالإنسان وفق القيم الوطنية والدينية، وتدعم التعليم وتنمية الموارد البشرية عربياً وعالمياً.","الرسالة: إعداد خريجين مؤهلين يعتزون بتراثهم، ويلتزمون بأخلاقيات المهنة، ويمتلكون مهارات معرفية وتقنية، ويُجرون بحوثاً نوعية، ويقدمون خدمات مهنية في التعليم وتنمية الموارد البشرية تلبي احتياجات المجتمع.","من أهدافها: إعداد وتأهيل المعلمين للتعليم العام ورياض الأطفال والتربية الخاصة، وتنسيق برامج الدبلومات المهنية، وإجراء البحوث التربوية، وتقديم الاستشارات للجهات الحكومية والخاصة، ومواءمة البرامج مع احتياجات سوق العمل.","الأقسام الأكاديمية حسب صفحة الكلية (8): التربية (طلاب وطالبات)، تقنيات التعليم (طلاب وطالبات)، علم النفس (طلاب وطالبات)، المناهج وطرق التدريس (طلاب وطالبات)، التربية الفنية (طلاب وطالبات)، التربية البدنية (طلاب فقط)، التربية الخاصة (طلاب وطالبات)، رياض الأطفال (طالبات فقط).","الصفحة الرئيسية تذكر 7 أقسام بدون «التربية الخاصة»: Education، Physical Education، Art Education، Curriculum and Instruction، Education Technologies، Kindergarten، Psychology.","البكالوريوس: التربية الخاصة (مساري الإعاقة الفكرية وصعوبات التعلم)، التربية البدنية، التربية الفنية، رياض الأطفال.","الدبلومات: الدبلوم العام في التربية، الدبلوم العالي في القياس والتقويم التربوي، دبلوم الإرشاد الأسري، الدبلوم العالي في التوحد (قسم التربية الخاصة).","الماجستير: المناهج وطرق التدريس، القياس والتقويم التربوي، الإدارة التربوية، التربية البدنية، تقنيات التعليم، الإرشاد النفسي، سيكولوجية الإدمان، التربية الخاصة (مسار التوحد)، التربية الخاصة (مسار الموهبة والإبداع)."],"src":"https://www.jazanu.edu.sa/en/colleges/college-education/about-us"},{"title":"كلية الآداب والعلوم الإنسانية","path":["الكليات"],"facts":["الرؤية: أن تُعرف محلياً ودولياً بالتميز في البحث والدراسة في الآداب والعلوم الإنسانية، وأن تسهم في برامج التنمية.","مهام الكلية: وضع أوصاف وظيفية رسمية لجميع منسوبي الكلية، بناء ثقافة مؤسسية مشتركة قائمة على الشفافية والتواصل، تحقيق التميز والاعتماد الأكاديمي لبرامج الكلية، وضع شروط قبول واضحة وتيسير إجراءات التقديم وتحسين أداء الطلاب.","الأقسام الأكاديمية حسب الصفحة الرئيسية (7): اللغات الأجنبية، الصحافة والإعلام، اللغة العربية وآدابها، العلوم الاجتماعية، الفنون، العلوم النفسية والسلوكية، العلوم التربوية.","البرامج المدرجة: الفنون التطبيقية، الصحافة الإلكترونية والنشر، الآثار، العلوم الاجتماعية، التربية الخاصة ، ضمن قسم العلوم النفسية والسلوكية، التصميم الداخلي."],"src":"https://www.jazanu.edu.sa/en/colleges/college-arts-and-humanities"},{"title":"كلية الشريعة والقانون","path":["الكليات"],"facts":["التأسيس: صدرت الموافقة على إنشائها في 21/01/1432هـ، والدراسة فيها بنظام الفصول الدراسية.","الرؤية: أن تكون صرحاً معرفياً وبحثياً شرعياً وقانونياً متميزاً يجمع بين الأصالة والمعاصرة، ويسهم في المجتمع ويقود محلياً وعالمياً.","مهام الكلية: العمل وفق التوجهات الثلاثة لجامعة جازان، ومعايير هيئة تقويم التعليم، وبرنامج التحول الوطني، ورؤية المملكة 2030. وتريد أن يؤدي خريجوها دوراً متميزاً في حماية مقاصد الشريعة وتعزيز الوسطية وقيم الإسلام.","الأقسام الأكاديمية (3): الشريعة، القانون العام، القانون الخاص.","برامج ووحدات أخرى: الدبلوم العالي في المحاماة، وحدة مواد الإعداد العام، وحدة الدراسات العليا.","التواصل: بريد العميد: mjaddoh@jazanu.edu.sa، الهاتف: 0173243005، الموقع: كلية الشريعة والقانون، جامعة جازان، أبوعريش، ساعات مقابلة العميد يومياً: 10:00–11:00 لأعضاء هيئة التدريس، و11:00–12:00 للطلاب والمراجعين."],"src":"https://www.jazanu.edu.sa/en/colleges/college-sharia-and-law"},{"title":"الكلية التطبيقية","path":["الكليات"],"facts":["العميد: Dr. Ali bin Abdulhadi Al-Almai، ويرد اسمه أيضاً Dr. Ali Abdul-Hadi Al-Almai Al-Asiri. صفحة الكلية تذكر أنه أول أكاديمي سعودي يحصل على رتبة أستاذ مشارك في إدارة السياحة والضيافة، وأنه حاصل على الدكتوراه من Texas Tech University.","نبذة: أُنشئت بتحويل كلية المجتمع بجامعة جازان إلى كلية تطبيقية، تماشياً مع رؤية المملكة 2030 واحتياجات سوق العمل.","الرؤية: إعداد خريجين متميزين أكاديمياً ومهنياً وأخلاقياً لتلبية احتياجات سوق العمل وفق رؤية 2030.","مهام الكلية: إتاحة فرص مواصلة الدراسة الجامعية لخريجي وخريجات الثانوية، إعداد الطلاب لوظائف مناسبة في سوق العمل، بناء شراكات استراتيجية مع القطاعات العام والخاص وغير الربحي، تقديم تدريب نوعي متخصص للقطاعات المستفيدة، دراسة احتياجات المنطقة لدعم التنمية المستدامة، تحديث البرامج التطبيقية والمهنية باستمرار.","البرامج: صفحة الكلية الرئيسية لا تسرد البرامج. ووردت في الصفحة الرئيسية للجامعة برامج دبلوم تحت عنوانين، لكن الموقع لا ينسبها صراحةً إلى الكلية التطبيقية: برامج غير مدفوعة، البرمجة وتشغيل الحاسب، تحليل وتصميم النظم، برامج مدفوعة، التسويق، المحاسبة، إدارة المكاتب، إدارة الأعمال، الفندقة والسياحة، إدارة المخاطر."],"src":"https://www.jazanu.edu.sa/en/colleges/applied-college"},{"title":"الكلية الجامعية بفرسان","path":["الكليات"],"facts":["العميدة: Dr. Afaf Muhammad Ba Ba'ir","نبذة: أُنشئت عام 1422/1423هـ كلية تربية، ثم انضمت إلى جامعة جازان باسم «كلية العلوم والآداب بفرسان»، ثم أصبحت الكلية الجامعية بفرسان.","الرؤية: التميز في التعليم والبحث، وبناء مهارات اجتماعية متنوعة تدعم التنمية محلياً ودولياً.","الرسالة والأهداف: تنفيذ سياسة التعليم في المملكة بتيسير الوصول إلى الدراسة الجامعية والسعي إلى الاعتماد الأكاديمي، تعزيز البحث العلمي ذي الأثر الدولي، توفير بيئة تعليمية محفزة لنجاح الطلاب والتطور المهني لأعضاء هيئة التدريس.","الأقسام الأكاديمية حسب الصفحة الرئيسية (4): العلوم الطبية ، وكان يقدم برنامج التمريض، الاقتصاد المنزلي، اللغة الإنجليزية، تقنية المعلومات والأمن."],"src":"https://www.jazanu.edu.sa/en/colleges/university-college-farasan"},{"title":"الكلية الجامعية بالدرب","path":["الكليات"],"facts":["نبذة: أُنشئت عام 1431–1432هـ، وتذكر صفحتها أن لها 5 أقسام أكاديمية. ومن مهامها إعداد الشابات السعوديات للعمل الأكاديمي والبحثي وسوق العمل والدراسات العليا.","الرؤية: أن تكون كلية متميزة رائدة في التعليم والبحث وذات أثر مجتمعي، وفق قيم وأهداف داعمة لرؤية 2030.","الرسالة والمهام: بناء بيئة تعليمية محفزة للتميز والتفكير الإبداعي، إعداد الشابات السعوديات للعمل الأكاديمي والبحثي وسوق العمل والدراسات العليا، توسيع الدور المجتمعي للكلية عبر شراكات أوسع.","الأقسام حسب صفحة الكلية (5، بكالوريوس): اللغة الإنجليزية، الرياضيات، الأحياء، إدارة الأعمال، التمريض.","الأقسام حسب الصفحة الرئيسية (7): الأحياء، اللغة الإنجليزية، الرياضيات، إدارة الأعمال، العلوم الطبية، وفيه برنامج التمريض، الكيمياء، علوم الحاسب.","صفحة «معلومات عن برامج البكالوريوس» تذكر الفيزياء بدلاً من الأحياء."],"src":"https://www.jazanu.edu.sa/en/colleges/university-college-darb"},{"title":"الكلية الجامعية بالدائر","path":["الكليات"],"facts":["نبذة: كان اسمها «كلية العلوم والآداب بالدائر»، وأُنشئت بالأمر السامي رقم (320/أ) وتاريخ 11/2/1432هـ، وتغير اسمها في العام الجامعي 1438/1439هـ.","الرؤية: إعداد الشابات السعوديات وفق رؤية 2030 للإسهام في تلبية احتياجات سوق العمل، وتشجيع البحث، وخدمة المجتمع والعمل التطوعي.","الرسالة: التميز الأكاديمي في المجالات الصحية والعلمية والأدبية، ورفع فاعلية البحث، وتقديم خدمات مجتمعية عملية عالية الأثر.","الأقسام حسب صفحة الكلية (3، بكالوريوس): الرياضيات، اللغة الإنجليزية، وكان في الأصل قسم الترجمة، التمريض، وافتُتح في العام الجامعي 1435–1436هـ.","الأقسام حسب الصفحة الرئيسية (5): التمريض، الرياضيات، اللغة الإنجليزية، الأحياء، الدراسات الإسلامية.","صفحة «معلومات عن برامج البكالوريوس» تضيف الفيزياء والكيمياء."],"src":"https://www.jazanu.edu.sa/en/colleges/university-college-dair"},{"title":"الكلية التطبيقية بالعارضة","path":["الكليات"],"facts":["الرؤية: أن تكون من الكليات الرائدة المعروفة محلياً وإقليمياً في الجوانب الأكاديمية والبحث العلمي وخدمة المجتمع.","قيمها كما وردت تحت «مهام الكلية»: القيادة الفاعلة، الجودة والتميز، الانتماء المؤسسي، الاحترام والعدل، المواطنة وخدمة المجتمع.","الأقسام حسب الصفحة الرئيسية (3): الموارد البشرية، تقنية حماية البيئة، العلوم الطبية.","الأقسام حسب صفحة الكلية: العلوم الطبية، الفيزياء، اللغة الإنجليزية، وبرنامجها في مرحلة الإعداد للاعتماد، قسم العلاج الطبيعي، ورد ذكره في أخبار الصفحة.","صفحة «معلومات عن برامج البكالوريوس» تذكر الأحياء وإدارة الأعمال كذلك."],"src":"https://www.jazanu.edu.sa/en/colleges/university-college-al-aarda"},{"title":"الكلية التطبيقية بصامطة","path":["الكليات"],"facts":["الأقسام حسب الصفحة الرئيسية (4): الفيزياء، الكيمياء، الاقتصاد المنزلي، رياض الأطفال.","صفحة «معلومات عن برامج البكالوريوس» تضيف التغذية الإكلينيكية ."],"src":"https://www.jazanu.edu.sa/en/colleges/university-college-samtah"},{"title":"الكلية الجامعية بأبوعريش","path":["الكليات"],"facts":["الرؤية: الارتقاء بمستوى أقسامها وبناء ريادة محلية وعالمية في مجتمع المعرفة، عبر بحوث مبتكرة بالتعاون مع كليات الجامعة الرئيسة. ومجالات تركيزها: تقنية المعلومات والأمن، والتغذية الإكلينيكية، والتسويق والتجارة الإلكترونية.","الرسالة: التميز الأكاديمي من خلال: تحسين مخرجات التعليم والتعلم وجودة البرامج، استقطاب أعضاء هيئة تدريس مؤهلين، توظيف التقنية لتوسيع فرص التعلم، تطوير البنية التحتية.","نبذة: بدأت عند افتتاحها بثلاثة أقسام: التغذية الطبية، ونظم المعلومات الحاسوبية، والتسويق والتجارة الإلكترونية.","الأقسام الحالية (4): التغذية الإكلينيكية، التسويق والتجارة الإلكترونية، تقنية المعلومات والأمن، الفيزياء . يرد في صفحة الكلية والصفحة الرئيسية، لكنه لا يتفق مع مجالات التركيز المعلنة.","صفحة «معلومات عن برامج البكالوريوس» تذكر علوم الحاسب بدلاً من الفيزياء."],"src":"https://www.jazanu.edu.sa/en/colleges/university-college-abo-arish"},{"title":"الكلية الجامعية بصبيا","path":["الكليات"],"facts":["لم يُعثر على صفحة تعريفية مستقلة للكلية ضمن البحث.","الأقسام حسب الصفحة الرئيسية (3): علوم الحاسب، المحاسبة، التمريض.","صفحة «معلومات عن برامج البكالوريوس» تذكر المحاسبة والتمريض فقط."],"src":"https://www.jazanu.edu.sa/en"},{"title":"الهيكل العام كما ورد في صفحة «الهيئات الجامعية»","path":["الوكالات والعمادات"],"facts":["الوكالات (5)","University Vice Presidency (وكالة الجامعة)","University Vice Presidency for Development and Entrepreneurship (وكالة الجامعة للتطوير وريادة الأعمال)","University Vice Presidency for Graduate Studies and Scientific Research (وكالة الجامعة للدراسات العليا والبحث العلمي)","University Vice Presidency for Academic Affairs (وكالة الجامعة للشؤون الأكاديمية)","University Vice Presidency for Student Affairs (وكالة الجامعة لشؤون الطالبات)","العمادات (9)","Deanship of Scientific Research (عمادة البحث العلمي)","Deanship of Postgraduate Studies (عمادة الدراسات العليا)","Deanship of Academic Development (عمادة التطوير الأكاديمي)","Deanship of Admission and Registration (عمادة القبول والتسجيل)","Deanship of E-Learning and Distance Education (عمادة التعليم الإلكتروني والتعلم عن بعد)","Deanship of Student Affairs (عمادة شؤون الطلاب)","Deanship of Library Affairs (عمادة شؤون المكتبات)","Deanship of Community Service and Continuing Education (عمادة خدمة المجتمع والتعليم المستمر)","Deanship of Human Resources (عمادة الموارد البشرية)"],"src":"https://www.jazanu.edu.sa/en/university-history/strategic-plan"},{"title":"وكالة الجامعة","path":["الوكالات والعمادات","الوكالات"],"facts":["الإنشاء: أُنشئت بقرار مجلس التعليم العالي رقم 8/39/1426 وتاريخ 25/10/1426هـ.","الرؤية (بتصرف من النسخة الإنجليزية): تتمحور حول تحقيق معايير الجودة، ومواكبة التطورات العالمية، والتميز المستدام في أداء المهام والمسؤوليات المنوطة بها. (تذكر الصفحة أن الوكالة تسعى لتحقيق رؤيتها ورسالتها وأهدافها انطلاقاً من قيم أساسية، دون سردها.)","الجهات المرتبطة بالوكالة (عمادات وإدارات): Deanship of Human Resources (عمادة الموارد البشرية)، General Administration of Administrative and Financial Affairs (الإدارة العامة للشؤون الإدارية والمالية)، General Administration of Projects (الإدارة العامة للمشاريع)، General Administration for Operation, Maintenance and Cleanliness (الإدارة العامة للتشغيل والصيانة والنظافة)، University Property Management and Wages (إدارة أملاك الجامعة والأجور)، Traffic and Transportation Administration (إدارة الحركة والنقل)، Office of External Contact Liaison (مكتب الاتصال الخارجي)، Administration of Resources and Sustainable Development (إدارة الموارد والتنمية المستدامة).","آخر تحديث للصفحة: الأحد 19 ربيع الآخر 1447هـ."],"src":"https://www.jazanu.edu.sa/en/administration/vice-rectorates/vice-president"},{"title":"وكالة الجامعة للشؤون الأكاديمية","path":["الوكالات والعمادات","الوكالات"],"facts":["المسؤول: د. حسن بن عبدالله علي إسحاق — وكيل الجامعة للشؤون الأكاديمية (وفق صفحة «كلمة الوكيل»؛ ويرد بالصفة نفسها أيضاً في خبر بتاريخ 01 صفر 1442هـ).","الإنشاء: أُنشئت بموجب الأمر السامي رقم 5150/م ب، بناءً على قرار مجلس التعليم العالي رقم 17/49/1429 في جلسته التاسعة والأربعين. وتُعد من الركائز الأساسية للجامعة، وتهدف إلى أن تتصدر الجامعات السعودية وأن تنال اعترافاً إقليمياً ودولياً بأنشطتها الأكاديمية والعلمية وخدماتها الطلابية وإسهامها في المجتمع.","رؤية الوكالة (النص كما ورد في النسخة الإنجليزية): \"Creating a distinguished and pioneering academic environment.\"","التوجه العام: تقديم برامج أكاديمية متميزة وفق أحدث معايير الجودة العالمية وبما يلبي احتياجات سوق العمل، عبر رفع مستوى أداء كليات الجامعة ودعم الطلاب وأعضاء هيئة التدريس.","مهام الوكالة: تهدف إلى دعم العملية التعليمية وتلبية احتياجات سوق العمل والحصول على الاعتماد الأكاديمي، ومن ذلك: إدارة العملية التعليمية وتوفير الموارد اللازمة لبيئة أكاديمية مستقرة ومحفزة على الإبداع والتميز، الإشراف على الكليات والعمادات والمراكز التابعة لها وتطوير أدائها، المساهمة في اختيار واستقطاب أعضاء هيئة التدريس المتميزين، وتوفير التدريب الذي يرفع كفاءتهم، الإشراف على تصميم الخطط والبرامج الدراسية وتطويرها وفق معايير المركز الوطني للتقويم والاعتماد الأكاديمي والهيئات المهنية الأخرى، ومتابعة تنفيذها وجودة مخرجاتها، إعداد الأدلة والنماذج التي توضح المتطلبات التعليمية والإجراءات والآليات المرتبطة بها.","أبرز ما ورد في كلمة الوكيل: استثمار المملكة في التعليم والعلم أساساً للتقدم؛ الالتزام بالتميز الأكاديمي وخدمة منسوبي الجامعة ومواكبة التوجهات العلمية والمجتمعية العالمية؛ من الأولويات: إبراز الإنجازات والأنشطة الطلابية والأكاديمية، وعقد شراكات مع مؤسسات تعليمية دولية لتطوير البرامج والمعايير، وبناء التواصل مع المجتمع المحلي دعماً للازدهار الاقتصادي والتعاون؛ ومواءمة أهداف الجامعة مع رؤية المملكة 2030.","صفحات فرعية: أدلة الوكالة : — صفحة التواصل (تعذّرت قراءتها): — موقع فرعي","آخر تحديث لصفحة الوكالة: الاثنين 28 ذو الحجة 1447هـ."],"src":"https://jazanu.edu.sa/en/administration/vice-rectorates/vice-president-academic-affairs"},{"title":"وكالة الجامعة للدراسات العليا والبحث العلمي","path":["الوكالات والعمادات","الوكالات"],"facts":["نبذة: أُنشئت مع إنشاء الجامعة بموجب أمر ملكي. تدعم تطوير الجامعة من خلال البحث العلمي، والشراكات البحثية مع القطاعات الخارجية، والمراكز البحثية المتخصصة. كما تخطط لكراسي البحث، وتوقّع الاتفاقيات مع الجهات المحلية والدولية، وتعمل على إصدار مجلة علمية متخصصة، وتشرف على الابتعاث، وعلى المجلس العلمي المختص باستقطاب أعضاء هيئة التدريس وترقياتهم والنشر.","الرؤية (النص كما ورد في النسخة الإنجليزية): \"Excellence in scientific research, and the development of high-level postgraduate programs\"","المهام: تعزيز البحوث المشتركة بين أعضاء هيئة التدريس والبرامج ذات الصلة والمعاهد البحثية، إيجاد آلية تشجع أعضاء هيئة التدريس على حضور المؤتمرات والندوات المحلية والدولية، تقديم المكافآت والبدلات للأعمال التي تسهم في البحوث المجتمعية، تولي الإجراءات المتعلقة بالمتطلبات.","الجهات التابعة: المراكز البحثية المتخصصة، كراسي البحث العلمي، المجلس العلمي، اللجان التي يرأسها وكيل الجامعة للدراسات العليا والبحث العلمي.","صفحات فرعية (تعذّرت قراءتها): منسوبو الوكالة: — عن الوكالة: — موقع فرعي","آخر تحديث للصفحة: الأربعاء 01 ربيع الآخر 1447هـ."],"src":"https://jazanu.edu.sa/en/administration/vice-rectorates/vice-president-graduate-studies-research"},{"title":"وكالة الجامعة للتطوير وريادة الأعمال","path":["الوكالات والعمادات","الوكالات"],"facts":["مدرجة ضمن وكالات الجامعة في صفحة «الهيئات الجامعية».","المسؤول (وفق خبر بتاريخ 19 محرم 1442هـ): صدر قرار تعيين د. نايف بن جحشور عزيبي وكيلاً للجامعة للتطوير وريادة الأعمال. ويرد بالصفة نفسها في خبر بتاريخ 01 صفر 1442هـ."],"src":"https://www.jazanu.edu.sa/en/media-center/news/president-jazan-university-issues-number-appointment-and-assignment-decisions"},{"title":"وكالة الجامعة لشؤون الطالبات","path":["الوكالات والعمادات","الوكالات"],"facts":["الاسم العربي مثبت في عنوان صفحة «نبذة عن وكالة الجامعة لشؤون الطالبات».","المسؤول (وفق خبر بتاريخ 01 صفر 1442هـ): Prof. Dr. Aisha bint Hassan Zikri — University Vice President for Student Affairs .","صفحات فرعية (تعذّرت قراءتها): نبذة عن الوكالة، المنسوبات، التواصل."],"src":"https://www.jazanu.edu.sa/en/media-center/news/vice-presidents-jazan-university-homeland-thriving-era-achievements-and-mega"},{"title":"عمادة القبول والتسجيل","path":["الوكالات والعمادات","العمادات"],"facts":["لم تتسنَّ قراءة الصفحة الرئيسية للعمادة (خطأ من جهة الموقع).","صفحات وخدمات ظاهرة في الموقع: خدمات عمادة القبول والتسجيل، بوابة القبول الإلكترونية، دليل البرامج وشروط القبول في جامعة جازان 2025–2026م (1447هـ)، صفحة التواصل، موقع فرعي إنجليزي، صفحات من الموقع القديم: التخرج، قبول الطالب المستجد، شروط الدبلوم التربوي، الاتصال بالعمادة ."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-admission-and-registration"},{"title":"عمادة الدراسات العليا / عمادة الدراسات العليا والبحث العلمي","path":["الوكالات والعمادات","العمادات"],"facts":["العميد: أ.د. صالح محمد صالح عبدالله — Dean of Postgraduate Studies (وفق صفحة العميد؛ وعنوان الصفحة: «عميد الدراسات العليا و البحث العلمي»).","نبذة: تشرف العمادة على الدراسات العليا والبحث، وتهدف إلى بناء بيئة أكاديمية وبحثية قوية تُخرّج كفاءات سعودية مؤهلة تسهم في تنمية المملكة وفق المعايير الدولية.","الرؤية (صيغتان في الموقع، بنصهما الإنجليزي): صفحة النبذة: \"Achieving excellence and leadership in postgraduate studies programs, both qualitative and quantitative.\"، صفحة العميد: أن تؤدي العمادة \"a pioneering and distinguished role in achieving distinction and leadership\" في برامج الدراسات العليا.","الأهداف: التوسع في برامج الدراسات العليا مع إعطاء الأولوية للتخصصات التي يحتاجها سوق العمل، استقطاب الطلاب المتميزين للالتحاق ببرامج الدراسات العليا، تحديث التدريس والبحث في مختلف المجالات الأكاديمية، تحسين العمليات الإدارية والأكاديمية بما يمكّن طلاب الدراسات العليا من الابتكار والتميز، بناء شراكات بحثية وطنية ودولية لتعزيز التصنيف البحثي لجامعة جازان، تنمية المهارات العلمية للطلاب وتشجيع الإبداع وتوجيه البحث نحو قضايا المجتمع السعودي، التعاون مع الجامعات ومراكز التميز البحثية.","صفحات فرعية: منسوبو العمادة: — اللجنة الدائمة للدراسات العليا: — مجلس عمادة الدراسات العليا: — موقع فرعي","خدمات ظاهرة في الموقع القديم: البرامج المتاحة للدراسات العليا، جميع النماذج ."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-graduate-studies/administration/deanships/aboutdeanship-graduate"},{"title":"عمادة البحث العلمي","path":["الوكالات والعمادات","العمادات"],"facts":["العميد (وفق صفحة كلمة العميد): د. أحمد عبدالحق علي عبدالحق — عميد البحث العلمي.","الدور (من كلمة العميد): الجهة المسؤولة عن تطوير منظومة البحث العلمي، بما يشمل قضايا التنمية العامة وقضايا منطقة جازان، التنسيق بين كليات الجامعة ومراكزها البحثية لتعزيز التعاون وحل التحديات البحثية، السعي إلى الشراكات وتبادل الأفكار مع جهات خارجية، منها مدينة الملك عبدالعزيز للعلوم والتقنية، ومؤسسات ومراكز بحثية داخل المملكة وخارجها، الهدف: الارتقاء بالبحث العلمي إلى أعلى المستويات.","صفحات فرعية: منسوبو العمادة: — التواصل"],"src":"https://www.jazanu.edu.sa/en/administration/deanships/srd/deanword"},{"title":"عمادة التطوير والجودة","path":["الوكالات والعمادات","العمادات"],"facts":["التسمية: ترد في الموقع باسم «عمادة التطوير والجودة» و«Deanship of Development and quality»، وفي صفحة «الهيئات الجامعية» باسم «Deanship of Academic Development».","الأهداف: تبني معايير الجودة العالمية، نشر الوعي بالجودة وتعزيز ثقافتها في الجامعة، تبادل الخبرات والتعاون مع منظمات الجودة المحلية والدولية، إجراء دراسات الجودة وتقديم المشورة لإدارات الجامعة في شؤون الجودة، تطوير العمل الأكاديمي وفق الخطط والأهداف الاستراتيجية للجامعة، السعي للاعتماد الوطني والدولي للبرامج الأكاديمية، تطبيق المعايير الدولية في تصميم البرامج والمقررات وتقويم الأداء، تنفيذ برامج تدريبية لتنمية مهارات أعضاء هيئة التدريس في التطوير الأكاديمي والجودة.","وحدات وإدارات ظاهرة في الموقع: وحدة الدراسات الإحصائية والتقارير، إدارة التميز المؤسسي.","برامج: برنامج «ممارس» (وفق عناوين أخبار الموقع)."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-academic-development/about-deanship-0"},{"title":"عمادة الموارد البشرية والتقنية","path":["الوكالات والعمادات","العمادات"],"facts":["النشأة (كما وردت في الصفحة): أُنشئت العمادة بقرار مجلس التعليم العالي بتاريخ 19/3/1430هـ باسم «عمادة التعليم الإلكتروني والتعلم عن بعد»، بهدف دعم التطور العلمي في المملكة، لا سيما عبر التعليم الإلكتروني والتعلم عن بعد المعمول بهما في الجامعات العالمية الرائدة.","الرؤية (النص كما ورد في النسخة الإنجليزية): \"Achieving excellence in e-learning and leadership in the provision of e-services and technology solutions that are smart, comprehensive and of high quality.\"","الرسالة (النص كما ورد في النسخة الإنجليزية): \"The optimal and thoughtful employment of e-learning and information technology\" — بما يسهم في تحقيق الأهداف الاستراتيجية للجامعة في إطار رؤية المملكة 2030 ووفق معايير الجودة العالمية.","وكالات وإدارات ظاهرة في الموقع (عناوين صفحات لم تُقرأ محتوياتها): وكالة العمادة للموارد البشرية، إدارة عمليات الموارد البشرية والتقنية، إدارة خدمات المستفيد والدعم الفني، إدارة الرواتب والنفقات، إدارة التواصل الداخلي، مكاتب ووحدات العمادة، منسوبو العمادة، البرامج والدورات التدريبية.","آخر تحديث للصفحة: الأحد 26 ربيع الآخر 1447هـ."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/elit"},{"title":"عمادة شؤون الطلاب","path":["الوكالات والعمادات","العمادات"],"facts":["نبذة: من أهم عمادات الجامعة لارتباطها المباشر بالطلاب الذين هم أساس المؤسسة، ودورها خدمة الطلاب ورعايتهم، ومن هذا الدور تنبع أهميتها ومسؤوليتها.","الخدمات: السكن المناسب، التغذية الصحية، توفير الكتب الدراسية عبر مراكز بيع الكتب داخل الجامعة، خدمات التصوير بأسعار مخفضة، الإرشاد الأكاديمي، الإعانات والمساعدات والسلف للطلاب المحتاجين من صندوق الطلاب وفق لوائحه وأنظمته.","وكالات ظاهرة في الموقع: وكيل العمادة للخدمات الطلابية، وكيلة العمادة لشطر الطالبات / Vice Deanship for Female Student Affairs.","صفحات أخرى: كلمة العميد، منسوبو العمادة، منسوبات العمادة (تعذّرت قراءتها)."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-student-affairs"},{"title":"عمادة شؤون المكتبات","path":["الوكالات والعمادات","العمادات"],"facts":["لم تتسنَّ قراءة صفحات العمادة (خطأ من جهة الموقع).","صفحات ظاهرة في الموقع: عن العمادة: — السياسات والإجراءات","عنوان خبر في الموقع: «عمادة شؤون المكتبات تنتهي من إيداع ١٢٥ رسالة ماجستير»."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-library-affairs"},{"title":"عمادة خدمة المجتمع والتعليم المستمر","path":["الوكالات والعمادات","العمادات"],"facts":["لم تتسنَّ قراءة صفحة العمادة (خطأ من جهة الموقع).","ما يظهر في الموقع: تقدم العمادة دبلومات تأهيلية (منها دبلوم السكرتارية الطبية وفق صفحات الموقع القديم)، وعنوان خبر: «جامعة جازان تستحدث 4 دبلومات بعمادة خدمة المجتمع». صفحات الموقع القديم تشمل: القبول والتسجيل، التقديم للدبلومات، أعضاء هيئة التدريس بالعمادة."],"src":"https://www.jazanu.edu.sa/ser/en/home-en/"},{"title":"الشروط العامة للقبول في مرحلة البكالوريوس","path":["القبول والبرامج الأكاديمية"],"facts":["الإطار العام","وفق نظام الجامعات السعودية، يحدد مجلس الجامعة أعداد الطلاب المستجدين كل عام، ويحدد رئيس الجامعة آلية المفاضلة ومعاييرها بعد التشاور مع الكليات.","يتم أغلب القبول في البكالوريوس لخريجي الثانوية عبر نظام القبول الموحد المشترك بين الجامعات.","الشروط العامة","الحصول على شهادة الثانوية العامة أو ما يعادلها من داخل المملكة أو خارجها (العلوم الطبيعية أو التقنية بالنسبة لبرامج العلوم).","ألا يكون قد مضى على الحصول على شهادة الثانوية أكثر من خمس سنوات، ولمجلس الجامعة الاستثناء من هذا الشرط إذا وُجدت أسباب مقنعة.","اجتياز اختبارات المركز الوطني للقياس (اختبار القدرات العامة، والاختبار التحصيلي).","أن يكون المتقدم حسن السيرة والسلوك ولائقاً طبياً.","اجتياز أي اختبار أو مقابلة يقررها مجلس الجامعة.","الحصول على موافقة خطية من جهة العمل إذا كان المتقدم موظفاً.","تقديم جميع الوثائق المطلوبة خلال المدة المحددة.","ألا يكون المتقدم مفصولاً من جامعة أخرى لأسباب تأديبية أو تعليمية، ويُلغى قبوله إذا تبيّن ذلك لاحقاً.","لا يُقبل في الغالب من يحمل شهادة بكالوريوس أو ما يعادلها للحصول على بكالوريوس آخر، ولرئيس الجامعة الاستثناء.","لا يحق للمتقدم المقيّد في درجة علمية بجامعة أخرى قبول المقعد.","للجامعة إضافة شروط أخرى تعلنها وقت التقديم.","النسبة الموزونة (كما وردت في صفحة قسم الكيمياء، غير مؤرخة)","النسبة الموزونة — الثانوية العامة: 30%، القدرات العامة: 30%، التحصيلي: 40%","نسبة المعدل — الثانوية العامة: 40%، القدرات العامة: 60%، التحصيلي: لا يدخل","خطوات القبول","الترشيح الإلكتروني: يختار المرشح أحد ثلاثة خيارات: القبول والتأكيد، أو القبول مع التحسين (للانتقال إلى برنامج آخر إذا شغر مقعد)، أو الانسحاب.","عدم التأكيد خلال المهلة يُسقط القبول ويُغلق الحساب الإلكتروني.","يصبح المتقدم «مقبولاً مبدئياً» ثم «مقبولاً نهائياً»، ويظهر له إلكترونياً الكلية والتخصص والرقم الجامعي.","يمكن الانسحاب بعد الحصول على الرقم الجامعي بتعبئة نموذج إخلاء طرف، ويجوز التقديم مجدداً بعد مضي عامين دراسيين.","استكمال القبول النهائي بحجز موعد لاستلام البطاقة الجامعية.","مثال على شرط برنامج محدد","بكالوريوس الكيمياء: شهادة الثانوية العامة السعودية (القسم العلمي) أو ما يعادلها، بنسبة لا تقل عن 70%، للطلاب والطالبات."],"src":"https://www.jazanu.edu.sa/en/colleges/sci/chem/admis-req"},{"title":"قواعد التحويل","path":["القبول والبرامج الأكاديمية"],"facts":["أولاً: التحويل من جامعة أخرى إلى جامعة جازان (المادتان 42 و43)","أن يكون الطالب قد درس في كلية أو جامعة معترف بها.","ألا يكون مفصولاً من جامعته السابقة لأسباب تأديبية أو تعليمية، وإذا تبيّن ذلك بعد قبوله يُلغى قيده من تاريخ القبول.","ألا يقل معدله التراكمي عن 3.00 من 5.00.","موافقة عميد الكلية التي يرغب الطالب في التحويل إليها.","إنهاء إجراءات التحويل خلال الفترة المحددة في التقويم الجامعي، ويجوز التحويل في أي فصل دراسي وفق مواعيد الجامعة.","ألا تقل الوحدات التي يدرسها الطالب في جامعة جازان عن 60% من وحدات البكالوريوس.","يعادل مجلس الكلية المقررات بتوصية من الأقسام، وتُثبت المقررات المعادلة في السجل الأكاديمي دون احتسابها في المعدل التراكمي.","آلية التقديم: يقدم الطالب طلبه إلى عمادة القبول والتسجيل مرفقاً بسجله الأكاديمي ومفردات المقررات، وتُحال الملفات بعد الموافقة إلى الكلية للمعادلة. وتقدم الطالبات طلباتهن لوكالة العمادة بشطر الطالبات.","ثانياً: التحويل بين كليات الجامعة (المادتان 46 و47)","مرة واحدة فقط طوال مدة الدراسة، بموافقة عميدي الكليتين.","ألا يقل المعدل التراكمي عن 2.00 من 5.00، والأفضلية للمعدل الأعلى وبحسب الطاقة الاستيعابية.","ألا يكون قد مضى على قبول الطالب أكثر من أربعة فصول دراسية.","يكون التحويل إلى الكليات التي تقبل طلاباً مستجدين في الفصل نفسه.","يجوز لطالب كلية المجتمع التحويل إلى كليات العلوم وإدارة الأعمال والآداب والعلوم الإنسانية بحسب نوع شهادة الثانوية، بشرط ألا يقل معدله التراكمي عن 4.25 من 5.00.","تُثبت جميع المقررات السابقة وتقديراتها ومعدلاتها في السجل الأكاديمي.","لا يحق العدول عن التحويل بعد انتهاء مدة التقديم.","ثالثاً: التحويل بين التخصصات داخل الكلية (المادتان 48 و49)","يجوز بموافقة عميد الكلية وفق الضوابط التي يضعها مجلس الكلية، وتُثبت المقررات السابقة وتقديراتها في السجل.","رابعاً: تحويل الطالبات من الانتساب إلى الانتظام","التقديم إلكترونياً عبر موقع الجامعة في الفترة المحددة بالتقويم.","ألا تكون الطالبة مقبولة استثناءً من شرط مدة الثانوية العامة.","ألا تكون قد حوّلت من قبل.","ألا يقل معدلها التراكمي عن 3.50 من 5.00.","ألا يكون قد مضى على قبولها أكثر من أربعة فصول دراسية.","يتم التحويل في القسم الأكاديمي نفسه، ولا يشمل المقبولات في برنامج التعليم عن بعد.","الصفحة على موقع عمادة القبول والتسجيل القديم وغير مؤرخة، وأرقام المواد فيها قد تخص لائحة سابقة لـ«لائحة الدراسة والاختبارات» المقرة عام 1444هـ."],"src":"http://deanships.jazanu.edu.sa/adm/Pages/Conversion.aspx"},{"title":"برامج الدبلوم (منصة الدبلومات - مركز التعليم المستمر)","path":["القبول والبرامج الأكاديمية"],"facts":["برامج مدفوعة تقدَّم عن بعد، وتاريخ بدء جميعها المعلن على المنصة: 6 سبتمبر 2026.","يُذكر بجانب معظم البرامج خصم إضافي لأبناء الشهداء ومنسوبي الضمان الاجتماعي (دون تحديد قيمته).","دبلوم الإعلام الرقمي وصناعة المحتوى — المدة كما وردت: 24 ساعة، الرسوم (ريال): 6,050","دبلوم السلامة والصحة المهنية — المدة كما وردت: 24 ساعة، الرسوم (ريال): 7,700","دبلوم المراجعة الداخلية والالتزام — المدة كما وردت: 24 ساعة، الرسوم (ريال): 6,061","دبلوم إدارة الأزمات والكوارث — المدة كما وردت: 24 ساعة، الرسوم (ريال): 6,061","دبلوم مساعد القانوني — المدة كما وردت: 24 ساعة، الرسوم (ريال): 6,600","دبلوم الذكاء الاصطناعي وعلوم البيانات — المدة كما وردت: 24 ساعة، الرسوم (ريال): 7,200","دبلوم المحاسبة والتحليل المالي — المدة كما وردت: 24 ساعة، الرسوم (ريال): 6,600","دبلوم السكرتارية الطبية — المدة كما وردت: 24 ساعة، الرسوم (ريال): 5,500","دبلوم العلاقات العامة والاتصال المؤسسي — المدة كما وردت: 24 ساعة، الرسوم (ريال): 4,950","دبلوم إدارة المشاريع — المستوى (كما ورد في الاسم): مشارك مهني، المدة كما وردت: 30 ساعة، الرسوم (ريال): 6,000","دبلوم إدارة اللوجستيات وسلاسل الإمداد — المستوى (كما ورد في الاسم): مشارك مهني، المدة كما وردت: 30 ساعة، الرسوم (ريال): 7,935","دبلوم أمن المعلومات — المستوى (كما ورد في الاسم): متوسط مهني، المدة كما وردت: 60 ساعة، الرسوم (ريال): 8,500","دبلوم إدارة المستشفيات — المستوى (كما ورد في الاسم): متوسط مهني، المدة كما وردت: 60 ساعة، الرسوم (ريال): 8,400","دبلوم الموارد البشرية — المستوى (كما ورد في الاسم): متوسط مهني، المدة كما وردت: 60 ساعة، الرسوم (ريال): 8,800","زمالة القيادة التنفيذية (زمالة مهنية) — المدة كما وردت: 48 ساعة، الرسوم (ريال): 7,100"],"src":"https://platform.jazanu.edu.sa/programs"},{"title":"شروط وتعليمات الالتحاق ببرامج الدبلوم","path":["القبول والبرامج الأكاديمية"],"facts":["متطلبات القبول","شهادة الثانوية العامة السعودية أو ما يعادلها، وتحتاج الشهادات الصادرة من خارج المملكة إلى تصديق ومعادلة من وزارة التعليم أو الجهة المختصة.","رفع البيانات والمستندات عبر الموقع خلال المواعيد المحددة، مع استيفاء الشروط الخاصة بالبرنامج.","المستندات بصيغة PDF: الشهادة المصدقة، وصورة الهوية الوطنية أو جواز السفر.","التسجيل والدراسة","تُسجَّل المقررات آلياً وفق الخطة، ولا يحق الحذف أو الإضافة أو تغيير الشعبة بعد اعتماد الجدول.","الدراسة إلكترونية متزامنة، مع توفر فصول مسائية.","الحد الأعلى للعبء الدراسي: 18 ساعة للطالب المستمر، و21 ساعة للمتوقع تخرجه.","الرسوب والإعادة","عبر المنصة خلال المهلة المحددة، بعذر مقبول وبعد سداد رسوم الفصل.","المدة المسموحة: فصل واحد للدبلوم المشارك، وفصلان للدبلوم المتوسط. وعدم العودة بعد انتهاء التأجيل يعني طي القيد.","الانسحاب واسترداد الرسوم","قبل بدء الدراسة — نسبة الاسترداد: 90% (خصم 10% رسوماً إدارية)","الأسبوع الأول — نسبة الاسترداد: 75%","الأسبوع الثاني — نسبة الاسترداد: 50%","الأسبوع الثالث — نسبة الاسترداد: 25%","بعد ذلك — نسبة الاسترداد: لا استرداد","يسقط حق الاسترداد بعد 21 يوماً من بداية الفصل، وتستغرق معالجته من شهر إلى فصل دراسي. والانسحاب نافذ بعد موافقة الجهة المختصة ولا يمكن التراجع عنه.","طي القيد والفصل","يُطوى القيد تلقائياً عند الانقطاع فصلاً كاملاً دون تأجيل معتمد، أو بقرار إداري.","يُفصل الطالب أكاديمياً إذا انخفض معدله عن 2.00 من 4.00 بعد الإنذارات، أو تجاوز المدة النظامية.","الحضور والأعذار","يُرصد الحضور آلياً، والغياب بنسبة تزيد على 25% يحرم من الاختبار النهائي ويُرصد تقدير .","الأعذار المقبولة: الطبية الموثقة، ووفاة قريب من الدرجة الأولى (3 أيام)، والولادة للطالبات (أسبوع)، وحوادث السير، والمشكلات التقنية الموثقة أثناء الاختبار، وغيرها بتقدير الإدارة.","التظلم من النتائج خلال 15 يوماً برسوم 200 ريال للمقرر. والتظلم من العقوبات الانضباطية خلال 5 أيام عمل من الإخطار.","التقديرات","ممتاز — النسبة: 90% فأكثر","جيد جداً — النسبة: 80–89%","جيد — النسبة: 70–79%","مقبول — النسبة: 60–69%","راسب — النسبة: أقل من 60%","المعدل من 4.00، ويُحسب التراكمي بقسمة مجموع النقاط على مجموع الساعات المعتمدة.","معدل تراكمي لا يقل عن 2.00 من 4.00، واجتياز جميع المقررات، وسداد المستحقات، ومطابقة الاسم لجواز السفر.","يجوز لطالب الدبلوم المتوسط طلب التخرج بدبلوم مشارك بعد إنهاء العام الأول بشروط مماثلة.","رسوم إعادة إصدار الوثيقة أو السجل: 500 ريال.","الالتزامات المالية","قيمة البرنامج كاملة دين ثابت فور التسجيل، وتُسدد دفعة واحدة، أو على دفعتين (بداية الفصل ومنتصفه)، أو بأقساط شهرية.","يتوقف الوصول إلى المنصة تلقائياً عند التأخر في السداد، وتتدرج الإجراءات من التذكير إلى الإنذار ثم المطالبة القضائية.","التواصل: dip-support@jazanu.edu.sa"],"src":"https://platform.jazanu.edu.sa/pages/application-terms"},{"title":"برامج الدراسات العليا في كلية التربية","path":["القبول والبرامج الأكاديمية"],"facts":["المناهج وطرق التدريس — الدرجة: ماجستير في التربية، المسار: مشروع تخرج أو رسالة","القياس والتقويم التربوي — الدرجة: دبلوم عالٍ في التربية","الإدارة التربوية — الدرجة: ماجستير في التربية، المسار: مقررات ورسالة، أو مقررات ومشروع بحثي","التربية البدنية — الدرجة: ماجستير في التربية، المسار: رسالة أو مشروع بحثي","تقنيات التعليم — الدرجة: ماجستير، المسار: مقررات ورسالة، أو مقررات ومشروع بحثي","الإرشاد النفسي — الدرجة: ماجستير في التربية، المسار: مشروع بحثي أو رسالة","علم نفس الإدمان — الدرجة: ماجستير في التربية","الإرشاد الأسري — الدرجة: دبلوم","اضطراب التوحد (قسم التربية الخاصة) — الدرجة: دبلوم عالٍ","اضطراب التوحد — الدرجة: ماجستير في التربية الخاصة، المسار: مقررات ورسالة علمية","الموهبة والإبداع — الدرجة: ماجستير في التربية الخاصة، المسار: مقررات ومشروع بحثي"],"src":"https://www.jazanu.edu.sa/ar/colleges/college-education/postgraduate-programs"},{"title":"شروط القبول في ماجستير الرياضيات (مثال على شروط برامج الماجستير)","path":["القبول والبرامج الأكاديمية"],"facts":["الصفحة خاصة بالعام الجامعي 2022-2023 (1444هـ)، وآخر تعديل لها 9 جمادى الأولى 1444هـ.","الطاقة الاستيعابية: حتى 10 طالبات و10 طلاب.","استيفاء لائحة الدراسات العليا (المواد 13 و15 و18)، إضافة إلى: بكالوريوس في الرياضيات أو العلوم الرياضية من جامعة سعودية أو جامعة معترف بها من وزارة التعليم، تقدير عام «جيد» على الأقل في البكالوريوس، وتقدير «جيد جداً» على الأقل في التخصص، اجتياز اختبار التوفل بدرجة لا تقل عن 400 أو ما يعادلها، درجة لا تقل عن 60 في اختبار القدرات، اجتياز الاختبار التحريري للقسم بمتوسط 60%، ويجوز لمجلس القسم التوصية بالقبول عند عدم تحقق ذلك بشرط اجتياز مقررات تكميلية قبل بدء البرنامج، اجتياز المقررات التكميلية التي يحددها القسم إذا نقص سجل البكالوريوس بعض المتطلبات الأساسية."],"src":"https://jazanu.edu.sa/en/colleges/sci/math-department/admissionrequmastersmath"},{"title":"عمادة الدراسات العليا","path":["القبول والبرامج الأكاديمية"],"facts":["الرؤية: أن تكون برامج الدراسات العليا رائدة في الابتكار والجودة، وفق المعايير المعترف بها دولياً، مواكبةً لتطور الحقول المعرفية، وخادمةً للمجتمع السعودي وسوق العمل، في بيئة داعمة للتعليم والتعلم والبحث العلمي.","التوسع في برامج الدراسات العليا بالجامعة، مع إعطاء الأولوية للتخصصات التي يحتاجها سوق العمل.","تشجيع الطلاب المتميزين على الالتحاق ببرامج الدراسات العليا واستقطابهم.","تحديث أساليب التدريس والبحث في مختلف التخصصات.","آخر تحديث للصفحة: 28 ذو الحجة 1447هـ."],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-graduate-studies"},{"title":"الطلاب الدوليون والمنح الدراسية","path":["القبول والبرامج الأكاديمية"],"facts":["عن القسم: يتولى قسم المنح الدراسية بعمادة شؤون الطلاب استقطاب الطلاب الدوليين ورعايتهم، وتهيئة بيئة تعليمية وثقافية تساعدهم على النجاح الأكاديمي والاندماج الاجتماعي.","تعريف المنحة: مقعد دراسي يُمنح لطالب غير سعودي للدراسة في مؤسسة تعليمية بالمملكة، لحاملي الثانوية العامة أو درجة علمية من داخل المملكة أو خارجها.","أنواع المنح","المنح الخارجية: للطلاب المقيمين خارج المملكة.","المنح الداخلية: للطلاب المقيمين في المملكة إقامة نظامية.","الشروط العامة","تُستبعد الطلبات غير المستوفية للشروط أو للوثائق المطلوبة.","الموافقة الإلكترونية لا تعني القبول النهائي، ويُبلَّغ المتقدم بعد صدور الموافقة النهائية من الجهات المختصة.","المتقدم مسؤول عن صحة بياناته ووثائقه، وللجامعة رفض الطلب أو فصل الطالب المقبول إذا ثبت عدم صحتها.","تُطبَّق على الطلاب الدوليين النسب والأوزان نفسها المطبقة على الطلاب السعوديين في الاختبارات المعيارية.","تسري على الطلاب الدوليين جميع أنظمة الجامعة ولوائحها وتعليماتها.","قسم الطلاب: 920066664 تحويلة 1017","قسم الطالبات: 920066664 تحويلة 3319"],"src":"https://www.jazanu.edu.sa/en/administration/deanships/deanship-student-affairs/scholarships-department"},{"title":"الاعتماد المؤسسي","path":["القبول والبرامج الأكاديمية"],"facts":["جامعة حكومية في منطقة جازان جنوب غرب المملكة، تحت مظلة وزارة التعليم، وحاصلة على الاعتماد الأكاديمي من هيئة تقويم التعليم والتدريب.","تمنح درجات البكالوريوس والدراسات العليا في مختلف التخصصات، إضافة إلى برامج التعلم المستمر عبر مركز التعليم المستمر التابع لمعهد البحوث والخدمات الاستشارية."],"src":"https://platform.jazanu.edu.sa/university-brief"},{"title":"الإدارة العامة للاتصال والإعلام","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["الأقسام الظاهرة في الصفحة الرئيسية للإدارة (عناوين فقط، دون محتوى تفصيلي): نبذة عن الإدارة العامة، كلمة المشرف العام على الإدارة، الهيكل التنظيمي التفاعلي، الإدارات: الإدارة العامة والإدارات التابعة لها، المحتوى الإعلامي الرقمي: أخبار جامعة جازان وفعالياتها وإنجازاتها محليًا ودوليًا، الأدلة والنماذج الإدارية: النماذج المعتمدة ودليل حوكمة الخدمات، تواصل معنا: قنوات التواصل مع الإدارة وإداراتها، الرؤية والرسالة: رؤية الإدارة ورسالتها وأهدافها ونشأتها، منسوبو الإدارة العامة للاتصال والإعلام، شراكات الجامعة: الاتفاقيات والشراكات مع الجهات الحكومية والإعلامية، المساعدة والدعم: الاستفسارات والمقترحات وطلبات الدعم الفني.","من محتوى الصفحة: مشاركة الجامعة في المعرض الدولي للتعليم 2025 تحت شعار «حيث تلتقي المعرفة بالمستقبل»، ووسوم تخص شاشة الجامعة التلفزيونية، وحفل التخرج العشرين 2025، والمعرض الدولي للتعليم 2025، و«مرحبًا بالعالم 2034». تذكر الصفحة إحصاءات إعلامية للأعوام 2022–2024 دون أن تظهر أرقامها.","آخر تحديث للصفحة: الاثنين 28 ذو الحجة 1447هـ."],"src":"https://www.jazanu.edu.sa/en/administration/departments/general-administration-communication-and-media-2"},{"title":"Administration of University Safety and Security (السلامة والأمن الجامعي)","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["النشأة: أصدر رئيس الجامعة القرار رقم 3963 بتاريخ 21/1/1439هـ بدمج إدارة السلامة والصحة المهنية مع إدارة الأمن الجامعي في إدارة واحدة.","الرؤية: تقديم خدمات سلامة وأمن متميزة للجامعة ومنسوبيها وزوارها.","الرسالة والمهام: حماية الأرواح والمباني والممتلكات في وحدات الجامعة، إرساء السلامة والأمن في جميع وحدات الجامعة.","لم يرد في الصفحة اسم المدير ولا بيانات التواصل."],"src":"https://www.jazanu.edu.sa/en/administration/departments/administration-university-safety-and-security"},{"title":"الإدارة العامة للشؤون الإدارية والمالية","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["لها موقع فرعي مستقل بعنوان «General Administration for Administrative and Financial Affairs»"],"src":"https://www.jazanu.edu.sa/ar/administration/departments/administrative-financial-affairs-administration"},{"title":"إدارة المراجعة الداخلية","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["خبر ذو صلة: «جامعة جازان تنظم لقاءا إثرائيا في شهر المراجعة الداخلية»"],"src":"https://jazanu.edu.sa/en/administration/departments/follow-administration"},{"title":"الإدارة القانونية (مسار legal-administration)","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["صفحة «اهداف الإدارة»","صفحة «Regulations and Regulations» (الأنظمة واللوائح)"],"src":"https://www.jazanu.edu.sa/ar/administration/departments/legal-administration/law-goal"},{"title":"إدارة التشغيل والصيانة والنظافة (مسار administration-operation-maintenance-and-cleaning)","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["الاسم مأخوذ من مسار الرابط، ولم يظهر الاسم الرسمي."],"src":"https://www.jazanu.edu.sa/en/administration/departments/administration-operation-maintenance-and-cleaning/%D8%B9%D9%86-%D8%A7%D9%84%D8%A5%D8%AF%D8%A7%D8%B1%D8%A9-2"},{"title":"الاتصالات الإدارية (مسار administration-administrative-communications)","path":["الإدارات والمراكز والخدمات والتواصل","الإدارات العامة"],"facts":["ظهرت كذلك صفحة «التواصل» تحت مسار المراكز center-documents-and-administrative-communications (انظر «مركز الوثائق والاتصالات الإدارية» أدناه)."],"src":"https://jazanu.edu.sa/en/administration/departments/administration-administrative-communications/contact"},{"title":"معهد البحوث والخدمات الاستشارية","path":["الإدارات والمراكز والخدمات والتواصل","المراكز والمعاهد والكراسي البحثية والوحدات"],"facts":["العميد: د. محمد بن عبدالرحيم عقيل، بحسب ما ظهر في الصفحة، التي تتضمن إعلانًا مؤرخًا في 02 صفر 1442هـ، فقد لا يكون الاسم محدَّثًا.","من محتوى الصفحة: إعلان عن فتح التسجيل في «برنامج الخبير الاستشاري» الذي يهدف إلى تطوير أعضاء هيئة التدريس في العمل الاستشاري. يبدأ البرنامج مطلع ربيع الأول ويمنح شهادات معتمدة.","الرؤية: معهد وطني رائد ذو اعتراف دولي، قائم على خبرات متينة وقدرة تنافسية.","الرسالة: تقديم الخدمات الاستشارية وتنفيذ المشاريع البحثية وبناء شراكات استراتيجية تدعم التنمية المستدامة، عبر المهارات والخبرات المتخصصة والتعاون مع الشركاء.","القيم: الالتزام، الجودة، المرونة، الشفافية والنزاهة المهنية، العمل بروح الفريق.","الأهداف: تقديم خدمات أكاديمية واستشارية عالية الجودة، الاستفادة المثلى من الموارد المادية والبشرية للجامعة، تنمية الموارد الذاتية للجامعة، تعزيز التعاون بين الجامعة والجهات الأخرى.","وحدة نظم المعلومات الجغرافية التابعة للمعهد، على الموقع القديم"],"src":"https://jazanu.edu.sa/en/centers-and-institutes/research-and-consulting-services-institute"},{"title":"مركز التعليم المستمر والتدريب المهني، التابع لمعهد البحوث والخدمات الاستشارية (منصة platform.jazanu.edu.sa)","path":["الإدارات والمراكز والخدمات والتواصل","المراكز والمعاهد والكراسي البحثية والوحدات"],"facts":["نبذة: يقدم المركز برامج التعليم المستمر والتدريب المهني، وبرامج أكاديمية وتدريبية معتمدة تلبي احتياجات سوق العمل وتدعم رؤية المملكة 2030 في بناء رأس المال البشري، وتجمع برامجه بين الجانبين النظري والتطبيقي.","الرؤية: الريادة الإقليمية والوطنية في التعليم المستمر والتدريب المهني، وأن يكون الخيار الأول لقادة المستقبل.","الرسالة: تقديم تعليم وتدريب عالي الجودة يلبي احتياجات سوق العمل ويسهم في تنمية المجتمع ويدعم رؤية 2030.","القيم: الجودة والتميز، النزاهة والشفافية، الابتكار والإبداع، المسؤولية المجتمعية، التعاون والشراكة.","إنجازات معروضة: أكثر من 500 خريج، وأكثر من 2,000 ساعة تدريبية، وأكثر من 20 برنامجًا أكاديميًا، وأكثر من 10 سنوات من الخبرة.","التواصل: الهاتف وواتساب: 00966115007295، البريد الإلكتروني: dip-support@jazanu.edu.sa.","روابط من المنصة: التقديم للتدريس (تسجيل المدربين): ومثال على برامجها «دبلوم المراجعة الداخلية والالتزام»","تشير المنصة إلى موقع الدعم الفني للجامعة: tic.jazanu.edu.sa"],"src":"https://platform.jazanu.edu.sa/about"},{"title":"Center for Environmental Research and Studies (مركز البحوث والدراسات البيئية)","path":["الإدارات والمراكز والخدمات والتواصل","المراكز والمعاهد والكراسي البحثية والوحدات"],"facts":["نبذة: أحد المراكز البحثية المتخصصة في الجامعة. يجري أبحاثًا عالية الجودة ويقدم استشارات علمية، موجهة أساسًا إلى المجتمع المحلي في منطقة جازان، وله اتفاقيات ومذكرات تفاهم وطنية ودولية.","الرؤية: أن يكون مركزًا رائدًا في البحوث البيئية يخدم المجتمعات المحلية والإقليمية والدولية.","الرسالة: تهيئة بيئة داعمة لبحوث منافسة دوليًا تخدم البيئة محليًا وإقليميًا وعالميًا، من خلال استقطاب باحثين متميزين وتوفير إمكانات متقدمة وبناء شراكات مع الجهات ذات العلاقة.","لم يرد في الصفحة اسم المدير ولا بيانات التواصل."],"src":"https://www.jazanu.edu.sa/en/centers-and-institutes/center-research-environmental-studies"},{"title":"مركز العناية بالمستفيدين","path":["الإدارات والمراكز والخدمات والتواصل","المراكز والمعاهد والكراسي البحثية والوحدات"],"facts":["يسميه الموقع «مركز العناية بالمستفيدين»، ومساره ccc.","صفحة «Enquiry Center» (مركز الاستفسارات): ولها نسخ أخرى بعنوان «Enquiry Center - Cloned» على ccc/ask1 وccc/ask3.","صفحة ذات صلة: «وحدة دعم المستفيدين» تحت مسار educational-services-equipment-administration"],"src":"https://www.jazanu.edu.sa/en/centers-and-institutes/ccc"},{"title":"مركز علاقات الخريجين والتوظيف","path":["الإدارات والمراكز والخدمات والتواصل","المراكز والمعاهد والكراسي البحثية والوحدات"],"facts":["النشأة: أُنشئ بموافقة رئيس الجامعة وبناءً على طلب وكيل الجامعة للشؤون التعليمية.","نبذة: يساعد الخريجين على الحصول على وظائف في القطاعين الحكومي والخاص، ويعدّهم لسوق العمل عبر التدريب وورش العمل، ويحافظ على صلتهم المهنية والشخصية بالجامعة.","الرؤية: أن يكون مركزًا وطنيًا رائدًا ببرامج تطور مهارات الطلاب وتعزز التواصل بين الجامعة وخريجيها.","المهام: إعداد برامج وخطط عمل تربط مخرجات التعلم بالإطار الوطني للمؤهلات، دعمًا لرؤية 2030 والخطة الاستراتيجية للجامعة، دعم كليات الجامعة ومعاهدها بالمعلومات اللازمة.","في الصفحة أقسام «خدمات الخريجين» و«الإعلانات» و«الفعاليات»، لكنها خالية من التفاصيل.","آخر تحديث للصفحة: الثلاثاء 02 ربيع الثاني 1445هـ.","لم يرد في الصفحة اسم المدير ولا بيانات التواصل."],"src":"https://www.jazanu.edu.sa/en/centers-and-institutes/alumni-relations-employment-unit"},{"title":"الخدمات الإلكترونية الرئيسية (كما تعرضها الصفحة الرئيسية)","path":["الإدارات والمراكز والخدمات والتواصل","الخدمات الإلكترونية"],"facts":["النظام الأكاديمي — الفئة المستفيدة: الطلاب، أعضاء هيئة التدريس","نظام التعلم الإلكتروني — الفئة المستفيدة: الطلاب، أعضاء هيئة التدريس","منصة الخدمات الإلكترونية — الفئة المستفيدة: الموظفون، أعضاء هيئة التدريس","البريد الإلكتروني — الفئة المستفيدة: الطلاب، أعضاء هيئة التدريس، الموظفون","منصة الخدمات الإلكترونية: ورد اسمها في خبر بعنوان «التعريف بمنصة الخدمات الإلكترونية لجامعة جازان EJUST بالكلية الجامعية بصامطة»"],"src":"https://www.jazanu.edu.sa/en"},{"title":"الجهات المسؤولة عن الخدمات الإلكترونية والدعم الفني","path":["الإدارات والمراكز والخدمات والتواصل","الخدمات الإلكترونية"],"facts":["«إدارة الخدمات والتعاملات الإلكترونية»","«اتفاقية مستوى الخدمات الإلكترونية»","«خدمات عمادة التعليم الإلكتروني و تقنية المعلومات»","«إدارة خدمات المستفيد والدعم الفني»","موقع الدعم الفني للجامعة، بحسب إشارة منصة التعليم المستمر: tic.jazanu.edu.sa"],"src":"https://www.jazanu.edu.sa/en/administration/deanships/elit/etransaction"},{"title":"سياسة الخصوصية وملفات تعريف الارتباط (الموقع الرئيسي)","path":["الإدارات والمراكز والخدمات والتواصل","البيانات المفتوحة والسياسات والمنافسات والوظائف"],"facts":["تعرض الصفحة الرئيسية للموقع إشعار ملفات تعريف الارتباط بالنص: «مرحباً بك في موقع جامعة جازان! نحيطك علماً بأن موقع جامعة جازان يقوم بإستخدام خاصية ملفات تعريف الإرتباط لتلبية متطلبات الأمان الاساسية ولتوفير سهولة الوصول و تجربة مستخدم أفضل.» ويليه رابط «سياسة الخصوصية»."],"src":"https://jazanu.edu.sa/en/privacy-policy"},{"title":"سياسات أخرى منشورة","path":["الإدارات والمراكز والخدمات والتواصل","البيانات المفتوحة والسياسات والمنافسات والوظائف"],"facts":["«سياسة الاستخدام المقبول للأصول»، ملف PDF مرجعه NCA (الهيئة الوطنية للأمن السيبراني)، الإصدار 2.0، بتاريخ 01/01/2024","«سياسات المركز» لمركز التعليم الإلكتروني","«الشروط والأحكام لهاكاثون الابتكار الرقمي»"],"src":"https://jazanu.edu.sa/ar/administration/deanships/hr-it/policy"},{"title":"سياسات منصة التعليم المستمر","path":["الإدارات والمراكز والخدمات والتواصل","البيانات المفتوحة والسياسات والمنافسات والوظائف"],"facts":["سياسة الخصوصية (ملخص): البيانات المجمّعة: البيانات الشخصية التي يقدمها المستخدم عند التسجيل في البرامج التدريبية أو الخدمات الإلكترونية، مثل الاسم والعنوان والبريد الإلكتروني ورقم الهاتف، الغرض: تقديم الخدمات المطلوبة، والتواصل بشأن البرامج المسجَّل فيها، وتحسين جودة الخدمة، الاحتفاظ: تُحفظ البيانات بقدر الحاجة للغرض الذي جُمعت له، ثم تُحذف بطريقة آمنة، الوصول والأمان: يقتصر الوصول على الموظفين المخولين ومختصي المنصة لأغراض مهنية، مع تدابير أمنية صارمة، الالتزام: «نلتزم بعدم نشر أو مشاركة بياناتك مع أي جهة خارجية» دون موافقة صريحة، حقوق المستخدم: الاطلاع على بياناته وتصحيحها وطلب حذفها في أي وقت، عبر قنوات التواصل في المنصة.","سياسات وصفحات أخرى في المنصة: سياسة الدعم الفني، الشروط العامة للتقديم، سياسة النزاهة، سياسة الحضور الإلكتروني، الشروط والأحكام، سياسة تقييم الأنشطة والمهام، سياسة الرد على استفسارات المتدربين خلال فترة البرنامج، مبادرة تطوير الموظفين."],"src":"https://platform.jazanu.edu.sa/ar/policies/privacy"},{"title":"المنافسات والمشتريات","path":["الإدارات والمراكز والخدمات والتواصل","البيانات المفتوحة والسياسات والمنافسات والوظائف"],"facts":["«الرؤية والرسالة والقيم»","«أساليب الشراء»","«قسم المنافسات الحكومية»","«اللجنة الدائمة لفحص العروض»"],"src":"https://www.jazanu.edu.sa/ar/administration/departments/purchase-administration/procurement-department"},{"title":"الوظائف والتوظيف","path":["الإدارات والمراكز والخدمات والتواصل","البيانات المفتوحة والسياسات والمنافسات والوظائف"],"facts":["خدمة «التوظيف» ضمن الخدمات الإلكترونية","إعلان: «تعلن جامعة جازان عن فتح باب التقديم للرجال والنساء لشغل وظائفها عن طريق التعاقد على الكادر الصحي»","إعلان: «الإعلان عن التعاون»","خبر: «Jazan University invites applications from Saudi Nationals for academic positions»","صفحة «الإعلانات» على النطاق الفرعي rpsr (مسار hr)","التقديم للتدريس في منصة التعليم المستمر","انظر أيضًا «مركز علاقات الخريجين والتوظيف» أعلاه."],"src":"https://www.jazanu.edu.sa/ar/e-services/applyingforacademicjobs"},{"title":"بيانات الاتصال الرئيسية (صفحة «Contact Us» / مكتب رئيس الجامعة)","path":["الإدارات والمراكز والخدمات والتواصل","التواصل"],"facts":["الهاتف: 0173295000","الفاكس: 0173297003","التحويلات: مدير المكتب 7776، والسكرتارية 7779 أو 7778، والاتصالات الإدارية 7111 أو 7222.","العنوان البريدي: جامعة جازان، مكتب رئيس الجامعة، 6809، جازان 82817-2820، المملكة العربية السعودية. لم توضح الصفحة هل الرقم 6809 رقم صندوق بريد.","البريد الإلكتروني: صفحة مكتب الرئيس تذكره وسيلةً للتواصل، لكن العنوان نفسه لم يظهر.","استقبال المراجعين: أيام الاثنين والثلاثاء والأربعاء الساعة 1:00 ظهرًا، ويوم الثلاثاء مخصص لأعضاء هيئة التدريس والمنسقين والموظفين.","تعليمات المراسلة: يجب أن تتضمن الرسائل الموجهة إلى رئيس الجامعة الاسم الكامل ورقم الجوال، ويضيف الطالب رقمه الجامعي.","آخر تحديث لصفحة مكتب الرئيس: الخميس 21 ذو الحجة 1443هـ."],"src":"https://www.jazanu.edu.sa/en/contactinfo"},{"title":"العنوان الوطني وصفحات اتصال أخرى","path":["الإدارات والمراكز والخدمات والتواصل","التواصل"],"facts":["قنوات تواصل منصة التعليم المستمر: انظر كتلة «مركز التعليم المستمر والتدريب المهني» أعلاه."],"src":"https://www.jazanu.edu.sa/ar/nau"},{"title":"الأخبار","path":["الأخبار والفعاليات والإعلانات"],"facts":["رئيس جامعة جازان يدشن منصة الترقيات — أطلق رئيس الجامعة منصة إلكترونية جديدة مخصصة لملف الترقيات. — الرابط","رئيس جامعة جازان يدشن جائزة الجامعة للتميز لتعزيز الأداء المؤسسي وتحفيز الابتكار — أُطلقت جائزة داخلية للتميز هدفها، كما يذكر العنوان، رفع الأداء المؤسسي وتشجيع الابتكار. — الرابط","جامعة جازان تطلق سلسلة الدورات والورش للعام الجامعي 2026 — أعلنت الجامعة عن برنامج دورات وورش تدريبية يمتد على العام الجامعي 2026. — الرابط","جامعة جازان ومؤسسة «شربتلي لخدمة المجتمع» توقعان اتفاقية بناء «مسجد الشربتلي» بالمدينة الجامعية — اتفاقية مع مؤسسة مجتمعية لإنشاء مسجد داخل المدينة الجامعية. — الرابط","جامعة جازان تنضم إلى مبادرة «ائتلاف الجامعات» لتعزيز منظومة التعليم الإلكتروني — انضمت الجامعة إلى تحالف جامعي يعمل على تطوير التعليم الإلكتروني. — الرابط","جامعة جازان توقّع مذكرة تفاهم مع كلية منار الجنوب للعلوم والتقنية — وقّعت الجامعة مذكرة تفاهم للتعاون مع كلية منار الجنوب للعلوم والتقنية. — الرابط","رئيس جامعة جازان يدشن حزمة من المنصات الرقمية في ملتقى التحول الرقمي 2025 — أُطلقت مجموعة من المنصات الرقمية الجديدة على هامش ملتقى التحول الرقمي 2025. — الرابط","رئيس جامعة جازان يستقبل وفد صندوق أسر الشهداء والمصابين والأسرى والمفقودين — لقاء رسمي جمع رئيس الجامعة بوفد من الصندوق. — الرابط","عميد كلية الأعمال بجامعة جازان: طلابنا في صدارة الأولويات — تصريح لعميد كلية الأعمال يؤكد أن خدمة الطلاب أولوية الكلية. — الرابط","رئيس جامعة جازان يدشّن «مشتل غراس الجامعة» بالتعاون مع بنك الجزيرة — افتُتح مشتل نباتي للجامعة بشراكة مع بنك الجزيرة. — الرابط"],"src":""},{"title":"الفعاليات","path":["الأخبار والفعاليات والإعلانات"],"facts":["طلبة كلية طب الأسنان يزورون القرية التراثية ضمن الأنشطة الطلابية لتعزيز الهوية الوطنية — زيارة ميدانية لطلبة الكلية إلى موقع تراثي ضمن أنشطة تعزيز الانتماء الوطني. — الرابط","تفعيل اليوم العالمي للأسرة بالمجمع الشرقي — فعالية بالمجمع الشرقي بمناسبة اليوم العالمي للأسرة. — الرابط","كلية طب الأسنان تنفذ حملة رقمية للتوعية بأضرار المخدرات — حملة توعوية نُفذت عبر القنوات الرقمية للتحذير من المخدرات. — الرابط","جامعة جازان تحتفي باليوم العالمي للتمريض 2026 — احتفاء الجامعة بالمناسبة العالمية لمهنة التمريض. — الرابط","اليوم العالمي للتعليم بفرع الكلية التطبيقية بالعارضة — فعالية بفرع العارضة بمناسبة اليوم العالمي للتعليم. — الرابط","الأسبوع الصحي البيئي «أثرك أخضر» بفرع الكلية التطبيقية بالعارضة — أسبوع توعوي يجمع بين الصحة والبيئة بفرع العارضة. — الرابط","فعالية «نحن بجانبك» لتعزيز الدعم النفسي لطالبات الكلية التطبيقية بالعارضة — فعالية لدعم الصحة النفسية لطالبات فرع العارضة. — الرابط","الكلية الجامعية بفرسان تدشن أعمال ملتقاها العلمي الرابع لتعزيز مخرجات البحث والابتكار — انطلقت الدورة الرابعة من الملتقى العلمي للكلية، وهي موجهة لدعم البحث والابتكار. — الرابط","كلية طب الأسنان تحتفي بالمنجزات العلمية في يوم البحث العلمي الحادي عشر وجائزة التميز الخامسة — احتفت الكلية بإنجازاتها البحثية في نسخة جديدة من يوم البحث العلمي، وكرّمت الفائزين بجائزة التميز. — الرابط","جامعة جازان تنظم فعالية يوم المهنة والبحث العلمي 2026 بكلية الصيدلة — فعالية سنوية في كلية الصيدلة تجمع بين التوظيف والبحث العلمي. — الرابط","أمير منطقة جازان يرعى حفلَ تخريج الدفعة الـ(21) من طلبة جامعة جازان — حفل تخريج الدفعة الحادية والعشرين برعاية أمير المنطقة. — الرابط","ورشة «صنع الإبداع والابتكار» بكلية الشريعة والقانون — ورشة عمل في كلية الشريعة والقانون تتناول تنمية الإبداع والابتكار. — الرابط","يوم مفتوح للبحث والابتكار في الكلية الجامعية بالداير — يوم مفتوح في كلية الداير لعرض أنشطة البحث والابتكار. — الرابط","فُرسَان الضاد: رحلة تأسيس لُغوية ملهمة في رحاب الكلية الجامعية بفرسان — برنامج في الكلية الجامعية بفرسان لتأسيس مهارات اللغة العربية. — الرابط","جامعة جازان تجمع المبتكرين في لقاء علمي ضمن «أسبوع الابتكار 2026» — لقاء علمي جمع المبتكرين ضمن فعاليات أسبوع الابتكار. — الرابط","ورشة «من الإلهام إلى الابتكار: بناء الحلول المبتكرة» في الكلية الجامعية بالداير — ورشة تطبيقية في كلية الداير على تحويل الأفكار إلى حلول مبتكرة. — الرابط","انطلاق أسبوع الابتكار في الكلية الجامعية بالدرب — بدأت فعاليات أسبوع الابتكار في الكلية الجامعية بالدرب. — الرابط","دورة «مهارات صياغة العقود القانونية» في كلية الشريعة والقانون — دورة تدريبية في كلية الشريعة والقانون على كتابة العقود القانونية. — الرابط","برج جامعة جازان يتوشّح بالأخضر احتفاءً بيوم العلم 2026 — أُضيء برج الجامعة باللون الأخضر احتفاءً بيوم العلم السعودي. — الرابط","اليوم العالمي للغة العربية بفرع الكلية التطبيقية بصامطة — فعالية في فرع صامطة بمناسبة اليوم العالمي للغة العربية. — الرابط","جناح جامعة جازان في «ملتقى الصحة العالمي» يستقبل قيادات وزارة الصحة — شاركت الجامعة بجناح في ملتقى الصحة العالمي، وزاره مسؤولون من وزارة الصحة. — الرابط","فعالية اليوم العالمي للمعلم في الكلية التطبيقية — فعالية في الكلية التطبيقية تكريماً للمعلم بمناسبة يومه العالمي. — الرابط","جامعة جازان تحتفي باليوم الوطني الـ95 في أجواء وطنية تخلّد الولاء والانتماء — احتفال الجامعة باليوم الوطني الخامس والتسعين للمملكة. — الرابط","كليات جامعة جازان تحتفل باليوم الوطني 95 بمجموعة متنوعة من الفعاليات — أقامت كليات الجامعة فعاليات متعددة احتفاءً باليوم الوطني الخامس والتسعين. — الرابط","رئيس جامعة جازان يلتقي بالطلبة المستجدين ويكرم المتفوقين — لقاء جمع رئيس الجامعة بالطلبة الجدد، وتكريم للمتفوقين منهم. — الرابط","كلية الشريعة والقانون تختتم فعاليات ملتقى التهيئة للطالبات المستجدات — اختُتم برنامج تهيئة الطالبات الجديدات في كلية الشريعة والقانون. — الرابط","رئيس جامعة جازان يدشّن ملتقى ومعرض استقبال الطلبة للعام الجامعي 1447هـ — افتُتح ملتقى ومعرض لاستقبال الطلبة الجدد مع بداية العام الجامعي 1447هـ. — الرابط"],"src":""},{"title":"الإعلانات","path":["الأخبار والفعاليات والإعلانات"],"facts":["بدون تاريخ — جائزة جامعة جازان للتميز 2026 (صفحة الخدمة الإلكترونية) — صفحة مخصصة لجائزة التميز لعام 2026، ولم تُعرف مواعيد الترشيح أو حالته لتعذّر فتحها. — الرابط","جامعة جازان تعلن عن التقويم الأكاديمي للدراسات العليا للعام الجامعي 2025-2026م — نشرت الجامعة التقويم الزمني لبرامج الدراسات العليا للعام 2025-2026م. — الرابط","جامعة جازان تعلن مواعيد التسجيل الذاتي للفصل الدراسي الأول 1447هـ — إعلان عن فترات التسجيل الذاتي للمقررات في الفصل الأول من عام 1447هـ. — الرابط","جامعة جازان تعلن عن مواعيد فتح التسجيل في المنح الدراسية لعام 1447هـ — إعلان عن فترة التقديم على المنح الدراسية الخاصة بعام 1447هـ. — الرابط","جامعة جازان تعلن الجدول الزمني للقبول للعام الجامعي 2025 — إعلان مواعيد مراحل القبول لبرامج العام الجامعي 2025. — الرابط","# ملتقى التحول الرقمي 2026 «قيمة وأثر» (من الدليل التعريفي للملتقى)"],"src":""},{"title":"البطاقة التعريفية للملتقى","path":["الملتقى"],"facts":["اسم الملتقى: ملتقى التحول الرقمي 2026، وهو النسخة الثالثة من الملتقى.","الشعار: «قيمة وأثر»، وعبارته: قيمة مؤسسية... وأثر ملموس.","الموعد: 16 – 17 نوفمبر 2026م، لمدة يومين.","الموقع: كلية الفنون والعلوم الإنسانية بجامعة جازان.","الجهة المنظمة: جامعة جازان ممثلة في عمادة الموارد البشرية والتقنية."],"src":""},{"title":"نبذة عن الملتقى","path":["الملتقى"],"facts":["في إطار سعي جامعة جازان إلى تعزيز نضج التحول الرقمي المؤسسي، وقياس القيمة المتحققة من المنصات والخدمات الرقمية، وإبراز أثرها على المستفيدين، يأتي ملتقى التحول الرقمي الثالث 2026 تحت شعار «قيمة وأثر» لاستعراض أهم المنجزات الرقمية للجامعة وأثرها على المستفيدين من داخل الجامعة وخارجها.","يأتي الملتقى متسقاً مع التوجهات الوطنية في عام الذكاء الاصطناعي 2026، ومع دور الجامعة في خدمة مجتمع منطقة جازان، من خلال إبراز الأثر الرقمي، واستعراض المبادرات النوعية، وتحفيز الابتكار، وتعزيز الشراكة مع الجهات الحكومية والتقنية ذات العلاقة."],"src":""},{"title":"إحصائيات الملتقى","path":["الملتقى"],"facts":["أكثر من 6500 زائر متوقع.","أكثر من 10 جهات مشاركة.","أكثر من 30 فعالية مصاحبة.","أكثر من 20 متحدثاً.","يضم الملتقى أنشطة وفعاليات تعكس حجم المشاركة والتفاعل، وتنوع الجهات المشاركة والمتحدثين والخبراء، والجلسات الحوارية وورش العمل والبرامج المصاحبة، والمبادرات والحلول الرقمية المعروضة."],"src":""},{"title":"أهداف الملتقى","path":["الملتقى"],"facts":["تعزيز ثقافة التحول الرقمي وإبراز منجزات التحول الرقمي بالجامعة.","توضيح أثر المنصات والخدمات الرقمية على تحسين تجربة المستفيدين.","ربط التحول الرقمي بتطبيقات الذكاء الاصطناعي والبيانات وذكاء الأعمال.","تعزيز ثقافة الابتكار الرقمي لتبني حلول رقمية مبتكرة داخل الجامعة.","إبراز دور الجامعة في خدمة المجتمع وتمكين مجتمع منطقة جازان رقمياً.","تعزيز الشراكات والتعاون مع الجهات الحكومية والخاصة في مجال التحول الرقمي."],"src":""},{"title":"الفئات المستهدفة","path":["الملتقى"],"facts":["مجتمع منطقة جازان.","أعضاء هيئة التدريس والموظفون.","طلبة الجامعة.","الجهات الحكومية بمنطقة جازان.","المختصون في التحول الرقمي.","الشركات التقنية ومزودو الحلول الرقمية.","رواد الأعمال والمبتكرون.","المستفيدون من الخدمات الرقمية."],"src":""},{"title":"أبرز الأركان والفعاليات","path":["الملتقى"],"facts":["المعرض الرقمي «قيمة وأثر»: استعراض أبرز مؤشرات الخدمات الرقمية عبر شاشات تفاعلية.","ركن الذكاء الاصطناعي والتقنيات الناشئة: استعراض أبرز الخدمات والمنجزات في الذكاء الاصطناعي.","ركن الابتكار الرقمي: استعراض المشاريع الرقمية الفائزة في المعسكر والمشاريع الطلابية.","ركن الرعاة والشركات التقنية: استعراض الحلول والمنتجات المقدمة من رعاة الملتقى.","ركن المجتمع الرقمي: استعراض أبرز المبادرات الرقمية بمجتمع منطقة جازان.","جلسات حوارية وورش عمل متخصصة: تقديم ورش العمل ودورات متخصصة في مجال التحول الرقمي."],"src":""},{"title":"موقع إقامة الملتقى","path":["الملتقى"],"facts":["يقام الملتقى في كلية الفنون والعلوم الإنسانية بجامعة جازان، في موقع جامعي متكامل يضع الجهات الراعية في قلب الحدث، ويمنحها فرصاً مباشرة للتواصل مع القيادات والخبراء والمختصين والمشاركين من داخل الجامعة وخارجها.","مساحة المعرض الرقمي: أجنحة الرعاة والخدمات الرقمية.","القاعة الرئيسية: الجلسات الحوارية وحفل الافتتاح.","قاعات الورش: ورش عمل متخصصة متوازية.","مساحات تفاعلية: شاشات وأركان رقمية تفاعلية."],"src":""},{"title":"فئات الرعاية","path":["الملتقى"],"facts":["الشريك الاستراتيجي: 250,000 ريال.","الشريك الأساسي: 150,000 ريال.","الراعي الماسي: 100,000 ريال.","من مميزات الرعاية: إدراج الشعار في الموقع الرسمي والمواد التعريفية والحملة الإعلانية، وذكر الجهة في الوسائل الإعلامية، وتخصيص جناح في المعرض الرقمي، وإبراز الشعار في الجلسات والشاشات وبطاقات التسجيل، وشهادة ودرع رعاية رسمية، وأولوية المشاركة في النسخ القادمة."],"src":""},{"title":"لماذا تشارك في الملتقى؟","path":["الملتقى"],"facts":["حضور مؤسسي نوعي: الارتباط بأكبر تجمع للتحول الرقمي في منطقة جازان بحضور القيادات والمختصين وصنّاع القرار.","وصول إعلامي واسع: ظهور الهوية عبر التغطيات الصحفية والقنوات الرقمية للجامعة قبل الملتقى وأثناءه وبعده.","فرص أعمال وشراكات: التواصل المباشر مع الجهات الحكومية والجامعية والشركات التقنية ورواد الأعمال.","استقطاب الكفاءات: الوصول إلى الطلاب والمبتكرين المشاركين في هاكاثون الابتكار الرقمي واكتشاف المواهب الرقمية.","مساهمة مجتمعية: دعم التمكين الرقمي لمجتمع منطقة جازان بما ينسجم مع مستهدفات رؤية المملكة 2030."],"src":""},{"title":"التواصل مع الملتقى","path":["الملتقى"],"facts":["الجهة: جامعة جازان، عمادة الموارد البشرية والتقنية.","الهاتف: 920066664.","البريد الإلكتروني: dxf@jazanu.edu.sa."],"src":""}];
